type Member = "saif" | "haneen";
type Engine = { id: number; title: string; subjectKey: string | null; subjectName: string | null; gradeLevel: string | null; unitName: string | null; lessonTitle: string | null; questionCount: number; difficulty: number; questionTimeLimitSeconds: number; status: "draft" | "ready" | "archived"; sourceCount: number };
type EngineDetail = Omit<Engine, "sourceCount"> & { sources: Array<{ id: number; sourceType: "lesson_note" | "study_file" | "text" | "url" | "image"; sourceRefId: number | null; label: string; pageStart: number | null; pageEnd: number | null; isPrimary: boolean }> };
type SourceOptions = { notes: Array<{ id: number; label: string; subjectName: string }>; files: Array<{ id: number; label: string; subjectName: string | null; pageCount: number | null; hasPageIndex: boolean }> };
type CompetitionQuestion = { id: number; questionType: string; prompt: string; explanation: string; evidenceQuote: string; difficulty: number };
type CurrentMatch = {
  match: { id: number; engineId: number; mode: "duel" | "rashed"; status: "waiting" | "ready" | "question_active" | "evaluating" | "showing_result" | "finished" | "cancelled"; currentQuestionOrder: number; questionTotal: number };
  players: Array<{ memberSlot: Member; state: "invited" | "joined" | "ready" | "disconnected" | "finished"; joinedAt: Date | null; readyAt: Date | null }>;
  question: { id: number; order: number; questionType: string; prompt: string; options: string[]; difficulty: number; imageUrl: string | null; deadlineAt: Date | null; status: string } | null;
  answerStates: Array<{ memberSlot: Member | "rashed"; submitted: boolean }>;
};
type PendingCompetitionInvitation = { matchId: number; engineTitle: string; createdBy: Member; createdAt: Date };
type EvaluatedMatch = CurrentMatch & {
  evaluations: Array<{ id: number; memberSlot: Member; outcome: "correct" | "partial" | "incorrect" | "manual_review"; confidence: number; awardedPoints: number; reason: string; reviewProposedOutcome: "correct" | "partial" | "incorrect" | "manual_review" | null; reviewProposedBy: Member | null; reviewConfirmedBy: Member | null; reviewNote: string | null }>;
  scores: Record<Member, number>;
  rashed: { name: "راشد"; submitted: boolean; answerText: string | null; rationale: string | null; behavior: "analysis" | "intentional_mistake" | null; outcome: "correct" | "partial" | "incorrect" | "manual_review" | null; confidence: number | null; awardedPoints: number | null; judgeReason: string | null; score: number } | null;
  rationales: Array<{ authorKey: Member | "rashed"; content: string; updatedAt: Date }>;
  loayReview: { reviewText: string; createdAt: Date } | null;
  result: { winnerSlot: Member | null; winnerKey: Member | "rashed" | null; completionReason: "completed" | "forfeit"; forfeitedBy: Member | null; saifPoints: number; haneenPoints: number; rashedPoints: number } | null;
};
type RationaleArchiveItem = { round: number; questionPrompt: string; opponentKey: Member | "rashed"; winnerKey: Member | "rashed" | null; rationales: Array<{ authorKey: Member | "rashed"; content: string }>; evaluations: Array<{ memberSlot: Member; outcome: "correct" | "partial" | "incorrect" | "manual_review"; awardedPoints: number; reason: string }>; rashed: { outcome: "correct" | "partial" | "incorrect" | "manual_review" | null; awardedPoints: number; answerText: string; rationale: string | null; judgeReason: string | null } | null; loayReview: string | null };
type CompetitionHistory = { wins: Record<Member, number>; completedCount: number; sessionCount: number; timedOutSessionCount: number; items: Array<{ id: number; matchId: number; winnerSlot: Member | null; saifPoints: number; haneenPoints: number; finishedAt: Date; engineTitle: string }>; sessionItems: Array<{ id: number; matchId: number; engineTitle: string; mode: "duel" | "rashed"; participants: Array<Member | "rashed">; winnerKey: Member | "rashed" | null; loserKey: Member | "rashed" | null; completionReason: "completed" | "forfeit"; forfeitedBy: Member | null; timedOutQuestionCount: number; saifPoints: number; haneenPoints: number; rashedPoints: number; finishedAt: Date }> };
type CompetitionStats = { completedMatches: number; players: Record<Member, { evaluated: number; correct: number; partial: number; incorrect: number; manualReview: number; accuracy: number; averageResponseSeconds: number | null }>; subjects: Array<{ subjectName: string; evaluated: number; correct: number; accuracy: number }> };
type WebSourceResult = { title: string; url: string; snippet: string; official: boolean };
type SourceInsight = { sourceId: number; sourceLabel: string; topics: Array<{ title: string; evidenceQuote: string }>; concepts: Array<{ term: string; explanation: string; evidenceQuote: string }>; updatedAt: Date };
type AutomaticWebResearch = { id: number; sourceId: number; query: string; results: Array<{ title: string; url: string; snippet: string; official: boolean }>; selectedSourceId: number; sourceLabel: string; selected: { id: number; label: string; sourceUrl: string | null } | null; createdAt: Date };
type AutomaticWebReader = { id: number; label: string; sourceUrl: string | null; contentSnapshot: string };
type CompetitionQuestionProgress = { status: "idle" | "running" | "completed" | "failed"; stage: "reading" | "generating" | "validating" | "saving" | "completed" | "failed"; totalSources: number; processedSources: number; totalBatches: number; processedBatches: number; currentSourceLabel: string | null; currentAttempt: number; maxAttempts: number; acceptedQuestions: number; rejectedQuestions: number; warnings: string[]; error: string | null };

const difficultyLabel = (value: number) => ["تمهيدي", "متوسط", "متقدم", "تحدّي"][value - 1] ?? "متوسط";
const questionTypeLabel: Record<string, string> = { multiple_choice: "اختيارات", true_false: "صح/خطأ", short_answer: "إجابة قصيرة", fill_blank: "أكمل", definition: "تعريف", explain: "شرح", compare: "مقارنة", ordering: "ترتيب", matching: "توصيل" };
const memberLabel = (member: Member) => member === "saif" ? "سيف" : "حنين";
const competitorLabel = (member: Member | "rashed") => member === "rashed" ? "راشد" : memberLabel(member);
const opponentLabelForMatch = (match: CurrentMatch, member: Member | null) => match.match.mode === "rashed" ? "راشد" : member ? memberLabel(match.players.find(player => player.memberSlot !== member)?.memberSlot ?? (member === "saif" ? "haneen" : "saif")) : "الطرف الآخر";
const roomStatusLabel: Record<CurrentMatch["match"]["status"], string> = { waiting: "مستنيين اللاعب التاني", ready: "اللاعبين دخلوا — استعدوا", question_active: "السؤال شغال", evaluating: "الإجابات تحت التقييم", showing_result: "النتيجة ظاهرة", finished: "المباراة خلصت", cancelled: "المباراة اتلغت" };
const ENGINE_START_SOUND_URL = "/manus-storage/engine-start-pixabay_8202bee5.mp3";
const COMPETITION_SOUND_STORAGE_KEY = "saf-haneen-competition-sound";
const COMPETITION_SOUND_EVENT = "saf-haneen-competition-sound-change";
const competitionSoundEnabled = () => typeof window === "undefined" || window.localStorage.getItem(COMPETITION_SOUND_STORAGE_KEY) !== "off";
const notifyCompetitionSoundChange = () => { if (typeof window !== "undefined") window.dispatchEvent(new Event(COMPETITION_SOUND_EVENT)); };
const RASHED_STATE_IMAGES = {
  question: "/manus-storage/rashed-robot-question_235a41f8.png",
  thinking: "/manus-storage/rashed-robot-thinking_fa67f223.png",
  correct: "/manus-storage/rashed-robot-correct_8dc32e89.png",
  incorrect: "/manus-storage/rashed-robot-incorrect_a758d83b.png",
  win: "/manus-storage/rashed-robot-win_3be6ad9e.png",
} as const;
type RashedVisualState = keyof typeof RASHED_STATE_IMAGES;
type CompetitionSpeechRecognition = { lang: string; interimResults: boolean; start: () => void; stop: () => void; onresult: ((event: { results?: ArrayLike<ArrayLike<{ transcript?: string }>> }) => void) | null; onerror: (() => void) | null; onend: (() => void) | null };

function RashedPortrait({ state, alt }: { state: RashedVisualState; alt: string }) {
  const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [state]);
  return failed ? <div className="rashed-portrait-fallback" role="img" aria-label={`${alt} — صورة بديلة`}><Bot size={42} /><span>راشد</span></div> : <img src={RASHED_STATE_IMAGES[state]} alt={alt} onError={() => setFailed(true)} />;
}

function CompetitionRashedPresence({ match, compact = false }: { match: CurrentMatch | EvaluatedMatch; compact?: boolean }) {
  if (match.match.mode !== "rashed") return null;
  const evaluated = match as EvaluatedMatch;
  const rashedOutcome = evaluated.rashed?.outcome;
  const winnerKey = evaluated.result?.winnerKey;
  const state: RashedVisualState = match.match.status === "question_active" ? "question" : match.match.status === "evaluating" ? "thinking" : match.match.status === "showing_result" ? rashedOutcome === "correct" ? "correct" : rashedOutcome === "partial" ? "thinking" : "incorrect" : match.match.status === "finished" && winnerKey === "rashed" ? "win" : "incorrect";
  const copy = state === "question" ? { eyebrow: "راشد استلم السؤال", title: "بيقرأ السؤال قبل ما يثبت رده", detail: "رده مجهز خادمياً لكنه مخفي لحد ما لؤي يحسم الجولة." } : state === "thinking" ? { eyebrow: "لؤي بيحسم الجولة", title: "الردود تحت التقييم", detail: "لا تُعرض إجابة راشد ولا نتيجتها قبل إعلان حكم لؤي." } : state === "correct" ? { eyebrow: "نتيجة راشد بعد الحسم", title: "لؤي صحّح رد راشد: إجابة صحيحة", detail: "راجعوا التعليل وحكم لؤي داخل نتيجة الجولة." } : state === "win" ? { eyebrow: "نتيجة المواجهة", title: "راشد أنهى المواجهة فائزاً", detail: "النتيجة تعليمية منفصلة عن سجل سيف وحنين الثنائي." } : { eyebrow: "نتيجة راشد بعد الحسم", title: "لؤي حدّد نقطة تحتاج تصحيحاً", detail: "راجعوا السبب وخطوة الإصلاح من لؤي، ثم كملوا الجولة التالية." };
  return <section className={`rashed-presence ${compact ? "is-compact" : ""} is-${state}`} aria-live="polite"><div className="rashed-presence-copy"><p className="card-kicker">{copy.eyebrow}</p><h2>{copy.title}</h2><p>{copy.detail}</p></div><figure className="rashed-presence-portrait"><RashedPortrait state={state} alt={`راشد في حالة: ${copy.title}`} /></figure></section>;
}

function readImageAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error("تعذر قراءة الصورة.")); reader.onload = () => typeof reader.result === "string" ? resolve(reader.result) : reject(new Error("تعذر قراءة الصورة.")); reader.readAsDataURL(file); });
}

function CompetitionEngineMotion({ engine, match, busy, showRashedCue = false }: { engine: EngineDetail | null | undefined; match: CurrentMatch | null | undefined; busy: boolean; showRashedCue?: boolean }) {
  const audio = useRef<HTMLAudioElement>(null!);
  const [soundOn, setSoundOn] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(competitionSoundEnabled);
  const running = Boolean(engine && (busy || engine.status === "ready" || (match && !["waiting", "cancelled", "finished"].includes(match.match.status))));
  const primed = Boolean(engine?.sources.length);
  const difficulty = match?.question?.difficulty ?? engine?.difficulty ?? 1;
  const progress = match?.question ? (match.question.order + 1) / Math.max(1, match.match.questionTotal) : 0;
  const steamLevel = !engine ? "idle" : match?.match.status === "question_active" && difficulty >= 4 ? "hot" : match?.match.status === "question_active" && (difficulty >= 3 || progress >= .65) ? "active" : running ? "ready" : primed ? "primed" : "idle";
  const steamDetail = steamLevel === "hot" ? "بخار أقوى لسؤال تحدٍّ" : steamLevel === "active" ? "بخار متصاعد مع تقدم الجولة" : steamLevel === "ready" ? "بخار ثابت أثناء استعداد الجولة" : steamLevel === "primed" ? "بخار هادئ مع المصادر الجاهزة" : "بخار هادئ في وضع الاستعداد";
  const status = !engine ? "في وضع الاستعداد" : busy ? "لؤي بيبني بنك الأسئلة" : engine.status === "ready" ? "البنك جاهز للمنافسة" : primed ? "المحرك متجهّز للمصادر" : "مستنيين مصادر الدراسة";
  useEffect(() => {
    const sync = () => setSoundEnabled(competitionSoundEnabled());
    window.addEventListener(COMPETITION_SOUND_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => { window.removeEventListener(COMPETITION_SOUND_EVENT, sync); window.removeEventListener("storage", sync); };
  }, []);
  useEffect(() => {
    const player = audio.current;
    if (!player || !soundEnabled) { audio.current?.pause(); setSoundOn(false); return; }
    player.currentTime = 0;
    void player.play().then(() => setSoundOn(true)).catch(() => setSoundOn(false));
    return () => { player.pause(); player.currentTime = 0; };
  }, [soundEnabled]);
  const triggerSound = async () => {
    if (!soundEnabled || !audio.current) return;
    try { audio.current.currentTime = 0; await audio.current.play(); setSoundOn(true); } catch { toast.error("المتصفح منع الصوت. جرّبه بعد أي نقرة داخل الصفحة."); }
  };
  return <section className={`competition-engine-motion is-present ${running ? "is-running" : primed ? "is-primed" : "is-idle"} steam-${steamLevel}`} aria-label={`حالة محرك المنافسة: ${status}. ${steamDetail}`}><div className="engine-copy"><p className="card-kicker">حالة المحرك</p><h2 className="text-lg font-black">{engine?.title || "محرك لؤي"}</h2><p className="mt-1 text-xs leading-6 text-[#718078]">{status}. {busy ? "تابع الشاشة؛ المرحلة الحالية ظاهرة في بطاقة التقدم أسفلها." : steamDetail}. البخار لا يغيّر حالة الجلسة أو حساب النقاط.</p><div className="mt-3 flex flex-wrap gap-2"><span className={`engine-status-chip ${running ? "is-active" : ""}`}>{status}</span><button type="button" onClick={() => { if (soundOn && soundEnabled) { audio.current?.pause(); audio.current.currentTime = 0; setSoundOn(false); } else if (!soundEnabled) { window.localStorage.setItem(COMPETITION_SOUND_STORAGE_KEY, "on"); setSoundEnabled(true); notifyCompetitionSoundChange(); } else void triggerSound(); }} className="engine-sound-toggle" aria-pressed={soundOn && soundEnabled}>{soundOn && soundEnabled ? "كتم صوت المحرك" : "تشغيل صوت المحرك"}</button></div>{showRashedCue ? <div className="engine-rashed-cue"><img src={RASHED_STATE_IMAGES.question} alt="راشد يستعد بجانب محرك المنافسة" /><span><strong>{match?.match.status === "question_active" ? "راشد بدأ يقرأ السؤال" : "راشد سمع المحرك وواقف على الاستعداد"}</strong><small>{match?.match.status === "question_active" ? "رده يظل مخفياً حتى يحسم لؤي الجولة." : "لن تفتح المواجهة قبل اكتمال بنك الأسئلة وبدء الغرفة."}</small></span></div> : null}</div><div className="engine-machine" aria-hidden="true"><span className="engine-steam steam-one" /><span className="engine-steam steam-two" /><span className="engine-steam steam-three" /><div className="engine-stack"><i /></div><div className="engine-pipe" /><div className="engine-boiler"><span className="engine-gauge" /><span className="engine-rivet r1" /><span className="engine-rivet r2" /><span className="engine-rivet r3" /></div><div className="engine-flywheel"><span /></div><div className="engine-base" /></div><audio ref={audio} preload="auto" src={ENGINE_START_SOUND_URL} onEnded={() => setSoundOn(false)} /></section>;
}

function CompetitionPreparationFlow({ engine, match, member, busy, preparing, automaticResearches, researchesLoading, onPrepare, onStart, onStartRashed, onJoin, onReady }: { engine: EngineDetail | undefined; match: CurrentMatch | null | undefined; member: Member | null; busy: boolean; preparing: boolean; automaticResearches: AutomaticWebResearch[]; researchesLoading: boolean; onPrepare: () => void; onStart: () => void; onStartRashed: () => void; onJoin: () => void; onReady: () => void }) {
  if (!engine) return null;
  const source = engine.sources.find(item => item.isPrimary) ?? engine.sources[0];
  const sourceRange = source?.pageStart ? source.pageEnd ? `من صفحة ${source.pageStart} إلى صفحة ${source.pageEnd}` : `من صفحة ${source.pageStart}` : null;
  const joined = match?.players.filter(player => player.state !== "invited").length ?? 0;
  const mine = match?.players.find(player => player.memberSlot === member);
  if (match && match.players.some(player => player.state === "disconnected")) return <CompetitionDisconnectNotice match={match} />;
  const preparationStages = source ? [
    { title: "المصدر الأساسي", detail: `اتسجل «${source.label}»${sourceRange ? ` ${sourceRange}` : ""} كلقطة موثقة للجولة.`, state: "complete" as const },
    { title: "دعم ويب موثّق", detail: researchesLoading ? "بنفحص سجل الدعم الموثق للمصدر…" : automaticResearches.length ? `اتسجل ${automaticResearches.length === 1 ? "بحث تلقائي واحد" : `${automaticResearches.length} عمليات بحث تلقائي`}؛ تقدروا تراجعوه من المصادر المساعدة.` : "ما اتسجلش مصدر ويب مساعد؛ لؤي هيعتمد على المصدر الأساسي بس.", state: automaticResearches.length ? "complete" as const : researchesLoading ? "active" as const : "pending" as const },
    { title: "بنك الأسئلة", detail: preparing ? "لؤي بيكوّن الأسئلة من اللقطة وبيتحقق من دليل كل سؤال قبل الحفظ." : engine.status === "ready" ? "اتحفظ البنك كامل واتقفل للتعديل لحماية تطابق أسئلة الجولة." : "مستنيين ضغطة التحضير عشان يبدأ توليد بنك موثّق.", state: preparing ? "active" as const : engine.status === "ready" ? "complete" as const : "pending" as const },
  ] : [];
  const preparationMap = preparationStages.length ? <section className="mt-4 rounded-2xl border border-[#dbe8d9] bg-white/80 p-3.5" aria-live="polite"><p className="text-xs font-black text-[#48654e]">خريطة التحضير الفعلية</p><ol className="mt-3 space-y-2.5">{preparationStages.map(stage => <li key={stage.title} className="flex items-start gap-2.5"><span className={`mt-0.5 grid size-5 shrink-0 place-items-center rounded-full ${stage.state === "complete" ? "bg-[#dff0df] text-[#2f6e43]" : stage.state === "active" ? "bg-[#fff0cf] text-[#9b6d26]" : "bg-[#edf1ed] text-[#718078]"}`}>{stage.state === "complete" ? <CheckCircle2 size={14} /> : <CircleDot size={14} />}</span><span><strong className="text-xs text-[#37483e]">{stage.title}</strong><span className="mt-0.5 block text-[11px] leading-5 text-[#718078]">{stage.detail}</span></span></li>)}</ol></section> : null;
  if (match?.match.mode === "rashed") return <section className="mb-5 overflow-hidden rounded-[1.45rem] border border-[#dcd4ef] bg-[#fbf9ff]"><div className="flex items-center gap-3 px-5 py-4"><div className="grid size-10 place-items-center rounded-2xl bg-[#eee8fb] text-[#604f90]"><Bot size={19} /></div><div><p className="card-kicker">مواجهة فردية</p><h2 className="text-lg font-black">أنت ضد راشد</h2><p className="mt-1 text-xs leading-6 text-[#6e6780]">راشد جهّز رده خادمياً، لكنه مخفي لحد ما لؤي يحسم الجولة.</p></div></div></section>;
  if (match) return <section className="mb-5 overflow-hidden rounded-[1.45rem] border border-[#cfe4d0] bg-[#f7fcf6]"><div className="border-b border-[#dcebdc] px-5 py-4"><p className="card-kicker">بدء المنافسة</p><h2 className="text-lg font-black">دخول اللاعبين: {joined} من 2</h2><p className="mt-1 text-xs leading-6 text-[#687a6d]">بعد اكتمال سيف وحنين وتثبيت الجاهزية، ينزل السؤال الأول نفسه للطرفين.</p></div><div className="grid gap-3 p-4 sm:grid-cols-2">{match.players.map(player => <div key={player.memberSlot} className={`flex items-center gap-3 rounded-2xl border p-3 ${player.state === "invited" ? "border-[#eadfca] bg-[#fffdf7]" : "border-[#cce2ce] bg-white"}`}><span className={`grid size-9 place-items-center rounded-full text-sm font-black ${player.state === "invited" ? "bg-[#f5ead3] text-[#9a733c]" : "bg-[#dff0df] text-[#317047]"}`}>{player.memberSlot === "saif" ? 1 : 2}</span><div><p className="text-sm font-black">{memberLabel(player.memberSlot)}</p><p className="mt-0.5 text-[11px] font-bold text-[#718078]">{player.state === "invited" ? "لم يضغط بدء المنافسة بعد" : player.state === "ready" ? "مكتمل وجاهز" : "دخل الغرفة"}</p></div></div>)}</div><div className="border-t border-[#dcebdc] px-5 py-4">{mine?.state === "invited" ? <button type="button" disabled={busy || !member} onClick={onJoin} className="rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">بدء المنافسة · دخول 2 من 2</button> : mine && mine.state !== "ready" && ["waiting", "ready"].includes(match.match.status) ? <button type="button" disabled={busy || !member} onClick={onReady} className="rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">تأكيد الجاهزية</button> : mine?.state === "ready" ? <p className="text-sm font-black text-[#3a7249]">تمّ تسجيلك. مستنيين الطرف الآخر لإطلاق السؤال الأول.</p> : null}</div></section>;
  if (engine.status === "ready") return <section className="mb-5 rounded-[1.45rem] border border-[#cfe4d0] bg-[#f7fcf6] p-5"><p className="card-kicker">الخطوة الأخيرة</p><h2 className="text-lg font-black">لؤي حضّر الأسئلة من المصدر المحدد</h2><p className="mt-1 text-xs leading-6 text-[#687a6d]">اختاروا مواجهة سيف وحنين، أو ادخلوا مباشرةً منافسة فردية ضد راشد.</p>{preparationMap}<div className="mt-4 flex flex-wrap gap-2"><button type="button" disabled={busy || !member} onClick={onStart} className="rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">بدء المنافسة · 1 من 2</button><button type="button" disabled={busy || !member} onClick={onStartRashed} className="inline-flex items-center gap-2 rounded-xl bg-[#62508f] px-4 py-3 text-sm font-black text-white disabled:opacity-50"><Bot size={16} />منافسة ضد راشد</button></div></section>;
  if (!source) return <section className="mb-5 rounded-[1.45rem] border border-dashed border-[#d9e5d8] bg-[#fbfdf9] p-5"><p className="card-kicker">الخطوة 1</p><h2 className="text-lg font-black">اختار كتابك وحدد الصفحات</h2><p className="mt-1 text-xs leading-6 text-[#718078]">يكفي كتاب واحد من «كتبي» أو PDF مرفوع مباشرةً. لا تحتاج أن ترفع مصدراً إضافياً.</p></section>;
  return <section className="mb-5 rounded-[1.45rem] border border-[#d8e8d8] bg-[#f8fcf6] p-5"><p className="card-kicker">الخطوة 2 · تحضير لؤي</p><h2 className="text-lg font-black">{preparing ? "لؤي يراجع المصدر ويحضر أسئلة الجولة…" : `لؤي جاهز يراجع «${source.label}»`}</h2><p className="mt-1 text-xs leading-6 text-[#687a6d]">{sourceRange ? `${sourceRange}. ` : ""}كل مرحلة تحت مبنية على حالة المحرك وسجل المصدر الموجودين فعلاً، مش تقدير أو نسبة شكلية.</p>{preparationMap}<button type="button" disabled={busy || !member} onClick={onPrepare} className="mt-4 rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">{preparing ? "لؤي بيحضّر الجولة…" : "خلّي لؤي يجهّز المنافسة"}</button></section>;
}

function CompetitionQuestionProgressPanel({ progress }: { progress: CompetitionQuestionProgress | undefined }) {
  if (!progress || progress.status === "idle") return null;
  const stageLabel = { reading: "بيقرأ المصادر", generating: "بيولّد أسئلة من المصدر الحالي", validating: "بيتحقق من الدليل ويمنع التكرار", saving: "بيحفظ البنك الموثوق", completed: "اكتمل البناء", failed: "توقف البناء" }[progress.stage];
  const batchPercent = progress.totalBatches ? Math.round((progress.processedBatches / progress.totalBatches) * 100) : 0;
  return <section className={`mb-5 rounded-[1.35rem] border p-4 ${progress.status === "failed" ? "border-[#efd2cf] bg-[#fff7f6]" : progress.status === "completed" ? "border-[#cfe4d0] bg-[#f7fcf6]" : "border-[#d9e3f0] bg-[#f8fbff]"}`} aria-live="polite"><div className="flex items-start justify-between gap-3"><div><p className="card-kicker">تقدم بناء بنك الأسئلة</p><h2 className="text-base font-black">{stageLabel}</h2><p className="mt-1 text-xs leading-6 text-[#6f7d75]">{progress.currentSourceLabel ? `المصدر الحالي: ${progress.currentSourceLabel}` : "المحرك يراجع كل مصدر قبل اعتماد السؤال."}</p></div><span className="rounded-full bg-white px-2.5 py-1 text-[11px] font-black text-[#466b83]">{progress.acceptedQuestions} سؤال موثوق</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#e6edf2]"><div className="h-full rounded-full bg-[#4d89a8] transition-all" style={{ width: `${progress.status === "completed" ? 100 : Math.max(4, batchPercent)}%` }} /></div><div className="mt-3 grid grid-cols-2 gap-2 text-[11px] font-bold text-[#6f7d75] sm:grid-cols-4"><span>المصادر: {progress.processedSources}/{progress.totalSources}</span><span>الدفعات: {progress.processedBatches}/{progress.totalBatches}</span><span>المحاولة: {progress.currentAttempt || 0}/{progress.maxAttempts}</span><span>المرفوض للتكرار/الغموض: {progress.rejectedQuestions}</span></div>{progress.warnings.length ? <div className="mt-3 rounded-xl bg-[#fff7e8] px-3 py-2 text-xs leading-6 text-[#896b38]">{progress.warnings[0]}</div> : null}{progress.error ? <div className="mt-3 rounded-xl bg-[#fff0ee] px-3 py-2 text-xs leading-6 text-[#a35d58]">{progress.error}</div> : null}</section>;
}

function CompetitionUnderstandingPanel({ insights, busy, onAnalyze }: { insights: SourceInsight[]; busy: boolean; onAnalyze: () => void }) {
  return <section className="mb-5 overflow-hidden rounded-[1.45rem] border border-[#d9e4ef] bg-[#f8fbff]" aria-live="polite"><div className="flex items-start gap-3 border-b border-[#e4edf4] px-5 py-4"><div className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#e5f0fa] text-[#4e7799]"><Bot size={21} /></div><div><p className="card-kicker">عقل لؤي قبل الأسئلة</p><h2 className="text-lg font-black">لؤي فهم إيه من الكتب؟</h2><p className="mt-1 text-xs leading-6 text-[#718078]">لن يبدأ صياغة السؤال قبل عرض الموضوعات والمفاهيم التي وجدها فعلاً في المصادر.</p></div></div>{insights.length ? <div className="grid gap-3 p-4 md:grid-cols-2">{insights.map(insight => <article key={insight.sourceId} className="rounded-2xl border border-[#e1eaf1] bg-white p-4"><p className="text-xs font-black text-[#4e7799]">{insight.sourceLabel}</p><div className="mt-3 flex flex-wrap gap-2">{insight.topics.map(topic => <span key={topic.title} className="rounded-full bg-[#edf5fb] px-2.5 py-1 text-[10px] font-black text-[#466b83]">موضوع: {topic.title}</span>)}</div>{insight.concepts.length ? <div className="mt-3 space-y-2">{insight.concepts.slice(0, 4).map(concept => <div key={concept.term} className="rounded-xl bg-[#f8fafc] px-3 py-2"><strong className="text-xs text-[#3f5565]">{concept.term}</strong><p className="mt-1 text-[11px] leading-5 text-[#718078]">{concept.explanation}</p></div>)}</div> : <p className="mt-3 text-xs text-[#9a6b39]">لم يجد لؤي مفاهيم موثوقة كافية من هذا المصدر.</p>}</article>)}</div> : <div className="p-5"><p className="text-sm font-bold text-[#5f7068]">لم نعرض فهم لؤي بعد. اضغط لتحليل كل مصدر قبل بناء البنك.</p><button type="button" disabled={busy} onClick={onAnalyze} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-[#4e7799] px-4 py-3 text-xs font-black text-white disabled:opacity-50"><Bot size={15} />{busy ? "لؤي بيقرأ ويفهم المصادر…" : "اعرض فهم لؤي أولاً"}</button></div>}</section>;
}

function CompetitionQuestionReviewPanel({ questions, busy, onConfirm }: { questions: CompetitionQuestion[]; busy: boolean; onConfirm: () => void }) {
  return <section className="mb-5 overflow-hidden rounded-[1.45rem] border border-[#eadfc8] bg-[#fffdf7]" aria-live="polite"><div className="flex items-start gap-3 border-b border-[#f0e7d6] px-5 py-4"><div className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#fff0cf] text-[#a8732d]"><CheckCircle2 size={21} /></div><div><p className="card-kicker">مراجعة يدوية قبل الإغلاق</p><h2 className="text-lg font-black">راجع بنك الأسئلة قبل بدء المنافسة</h2><p className="mt-1 text-xs leading-6 text-[#718078]">الأسئلة ما زالت مسودة. راجع الصياغة والدليل، ثم اقفل البنك عندما تكون راضياً عنه.</p></div></div><div className="max-h-[38rem] overflow-y-auto divide-y divide-[#f0e7d6]">{questions.map((question, index) => <article key={question.id} className="p-4"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#f3ead7] px-2 py-1 text-[10px] font-black text-[#8b672e]">سؤال {index + 1} · {questionTypeLabel[question.questionType] || question.questionType}</span><span className="text-[10px] font-bold text-[#8a938b]">{difficultyLabel(question.difficulty)}</span></div><p className="mt-3 text-sm font-black leading-7">{question.prompt}</p><p className="mt-3 rounded-xl bg-white px-3 py-2 text-xs leading-6 text-[#79623d]">الدليل: «{question.evidenceQuote}»</p></article>)}</div><div className="flex flex-wrap items-center justify-between gap-3 border-t border-[#f0e7d6] px-5 py-4"><p className="text-xs font-bold text-[#7b817b]">بعد الإغلاق فقط يمكن بدء مباراة سيف وحنين أو راشد.</p><button type="button" disabled={busy || !questions.length} onClick={onConfirm} className="rounded-xl bg-[#9b7131] px-4 py-3 text-xs font-black text-white disabled:opacity-50">{busy ? "جارٍ إغلاق البنك…" : "اعتماد البنك وإغلاقه"}</button></div></section>;
}

type EngineStep = "sources" | "prepare" | "mode";
type CompetitionMode = "duel" | "rashed";

function playReturnConfirmationTone() {
  if (!competitionSoundEnabled()) return;
  try {
    const AudioContextClass = window.AudioContext ?? (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextClass) return;
    const context = new AudioContextClass();
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = "sine";
    oscillator.frequency.setValueAtTime(620, context.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(470, context.currentTime + 0.14);
    gain.gain.setValueAtTime(0.0001, context.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.045, context.currentTime + 0.018);
    gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + 0.16);
    oscillator.connect(gain);
    gain.connect(context.destination);
    oscillator.start();
    oscillator.stop(context.currentTime + 0.17);
    window.setTimeout(() => void context.close(), 260);
  } catch {
    // بعض المتصفحات تمنع صوت التنبيه حتى يلمس المستخدم الصفحة؛ لا نعطل الرجوع.
  }
}

function CompetitionSoundToggle({ compact = false }: { compact?: boolean }) {
  const [enabled, setEnabled] = useState(competitionSoundEnabled);
  useEffect(() => {
    const sync = () => setEnabled(competitionSoundEnabled());
    window.addEventListener(COMPETITION_SOUND_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => { window.removeEventListener(COMPETITION_SOUND_EVENT, sync); window.removeEventListener("storage", sync); };
  }, []);
  const toggle = () => {
    const next = !enabled;
    window.localStorage.setItem(COMPETITION_SOUND_STORAGE_KEY, next ? "on" : "off");
    setEnabled(next);
    notifyCompetitionSoundChange();
    toast.info(next ? "المؤثرات الصوتية اتفتحت للمنافسة." : "المؤثرات الصوتية اتكتمت؛ الحركة البصرية هتفضل شغالة.");
  };
  return <button type="button" onClick={toggle} className={`competition-sound-toggle ${compact ? "is-compact" : ""}`} aria-pressed={enabled} title={enabled ? "كتم المؤثرات الصوتية" : "تشغيل المؤثرات الصوتية"}>{enabled ? "المؤثرات الصوتية: تشغيل" : "المؤثرات الصوتية: كتم"}</button>;
}

function CompetitionSoundPreferenceBar() {
  return <div className="competition-page-tools" aria-label="إعدادات المنافسة"><CompetitionSoundToggle /><span>تقدروا تكتموا المؤثرات من هنا، والحركة البصرية هتفضل موجودة.</span></div>;
}

function CompetitionSteamBackButton({ onConfirm }: { onConfirm: () => void }) {
  const [open, setOpen] = useState(false);
  const [returning, setReturning] = useState(false);
  const requestReturn = () => {
    playReturnConfirmationTone();
    setOpen(true);
  };
  const confirmReturn = () => {
    setOpen(false);
    setReturning(true);
    window.setTimeout(onConfirm, 180);
  };
  return <><div className="competition-navigation-tools"><button type="button" onClick={requestReturn} title="مراجعة ما سيُحفظ قبل الرجوع" className={`competition-steam-return mb-4 inline-flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-black ${returning ? "is-returning" : ""}`} aria-label="العودة إلى بطاقات المحرك"><span className="steam-return-puffs" aria-hidden="true"><i /><i /><i /></span><ChevronLeft size={16} strokeWidth={2.6} /><span>العودة للبطاقات</span></button><CompetitionSoundToggle compact /></div><AlertDialog open={open} onOpenChange={setOpen}><AlertDialogContent className="border-[#dbe7d8] bg-[#fffdfa] text-right"><AlertDialogHeader><p className="card-kicker">رجوع آمن · تلميح</p><AlertDialogTitle>ترجع لبطاقات المحرك؟</AlertDialogTitle><AlertDialogDescription className="space-y-2 leading-7"><span className="block rounded-xl bg-[#f3f8f1] px-3 py-2 text-xs font-black text-[#41674c]">الرجوع هنا بيغيّر الشاشة بس، ومش بيحذف أي حاجة محفوظة.</span><span className="block">هيفضل محفوظ: المصادر، لقطات الملفات، بنك الأسئلة، وسجل المنافسات والنتائج والإنجازات.</span><span className="block">ممكن تحتاج تختار نمط الغرفة من جديد لو كان اختياراً محلياً ولسه ما اتسجلش.</span></AlertDialogDescription></AlertDialogHeader><AlertDialogFooter className="flex-row-reverse gap-2 sm:justify-start"><AlertDialogCancel disabled={returning} className="border-[#d7e5d5] bg-white font-black text-[#41674c] hover:bg-[#f1f7ef]">البقاء في المحرك</AlertDialogCancel><AlertDialogAction disabled={returning} onClick={confirmReturn} className="bg-[#32624e] font-black hover:bg-[#294f3f]">{returning ? "راجعين للبطاقات…" : "العودة للبطاقات"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function CompetitionEngineGateway({ engine, activeStep, mode, busy, preparing, onOpenStep, onBack, onModeChange, onPrepare, onStartDuel, onStartRashed, onChangeEngine, onRequestDelete }: { engine: EngineDetail; activeStep: EngineStep | null; mode: CompetitionMode | null; busy: boolean; preparing: boolean; onOpenStep: (step: EngineStep) => void; onBack: () => void; onModeChange: (mode: CompetitionMode) => void; onPrepare: () => void; onStartDuel: () => void; onStartRashed: () => void; onChangeEngine: () => void; onRequestDelete: () => void }) {
  const hasSources = engine.sources.length > 0;
  const bankReady = engine.status === "ready";
  const back = <CompetitionSteamBackButton onConfirm={onBack} />;
  if (activeStep === "prepare") return <section className="mb-5 rounded-[1.45rem] border border-[#d8e8d8] bg-[#f8fcf6] p-5">{back}<p className="card-kicker">البطاقة 2 · تحضير لؤي</p><h2 className="mt-1 text-lg font-black">{bankReady ? "بنك الأسئلة جاهز" : hasSources ? "المصدر جاهز للمراجعة" : "أضيفوا المصدر أولاً"}</h2><p className="mt-2 text-sm leading-7 text-[#687a6d]">{bankReady ? "اكتمل البنك من مصادر الجلسة المحفوظة. انتقلوا الآن لاختيار الغرفة." : hasSources ? "لؤي سيبني البنك من المصادر المختارة فقط، ويتحقق من دليل كل سؤال قبل حفظه." : "ارجعوا إلى بطاقة مصدر الجلسة واختاروا كتاباً أو PDF أو صورة تعليمية."}</p>{bankReady ? <button type="button" onClick={() => onOpenStep("mode")} className="mt-4 w-full rounded-2xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white">اختاروا الغرفة المناسبة</button> : <button type="button" disabled={!hasSources || busy || preparing} onClick={onPrepare} className="mt-4 w-full rounded-2xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">{preparing ? "لؤي بيحضّر البنك…" : "خلّي لؤي يجهّز المنافسة"}</button>}</section>;
  if (activeStep === "mode") return <section className="mb-5 rounded-[1.45rem] border border-[#dcd9e9] bg-[#fbfaff] p-5">{back}<p className="card-kicker">البطاقة 3 · اختيار الغرفة</p><h2 className="mt-1 text-lg font-black">مين هيكون في المنافسة؟</h2><p className="mt-2 text-xs leading-6 text-[#6e687d]">اختيارك لا يغير بنك الأسئلة؛ هو فقط يحدد الغرفة التي سيفتحها الزر الأخضر.</p><div role="radiogroup" aria-label="نمط المنافسة" className="mt-4 grid gap-3 sm:grid-cols-2"><button type="button" role="radio" aria-checked={mode === "rashed"} onClick={() => onModeChange("rashed")} className={`rounded-2xl border p-4 text-right transition ${mode === "rashed" ? "border-[#665198] bg-[#f0ecfb]" : "border-[#e4dfed] bg-white"}`}><span className={`inline-block size-4 rounded-full border-4 ${mode === "rashed" ? "border-[#665198] bg-white" : "border-[#adb6ac] bg-white"}`} /><strong className="mr-2 text-sm">منافسة ضد راشد</strong><span className="mt-2 block text-xs leading-6 text-[#6e687d]">مواجهة فردية ورد راشد يظل مقفلاً حتى حكم لؤي.</span></button><button type="button" role="radio" aria-checked={mode === "duel"} onClick={() => onModeChange("duel")} className={`rounded-2xl border p-4 text-right transition ${mode === "duel" ? "border-[#4b8257] bg-[#edf7ec]" : "border-[#dbe7db] bg-white"}`}><span className={`inline-block size-4 rounded-full border-4 ${mode === "duel" ? "border-[#42764e] bg-white" : "border-[#adb6ac] bg-white"}`} /><strong className="mr-2 text-sm">منافسة سيف وحنين</strong><span className="mt-2 block text-xs leading-6 text-[#6d7b70]">غرفة مشتركة يدخلها الطرفان ويؤكدان الجاهزية.</span></button></div>{bankReady && mode ? <button type="button" disabled={busy} onClick={mode === "rashed" ? onStartRashed : onStartDuel} className="mt-4 w-full rounded-2xl bg-[#2d8a49] px-4 py-3.5 text-sm font-black text-white shadow-[0_12px_24px_rgba(45,138,73,.2)] transition hover:bg-[#24783e] disabled:opacity-50">{mode === "rashed" ? "بدء المنافسة ضد راشد" : "بدء المنافسة مع الطرف الآخر"}</button> : <p className="mt-4 rounded-xl bg-[#fff8ed] px-4 py-3 text-center text-xs leading-6 text-[#896a35]">جهّزوا بنك الأسئلة أولاً، ثم اختاروا نمط المنافسة.</p>}</section>;
  if (activeStep === "sources") return <section className="competition-engine-gateway mb-5 rounded-[1.45rem] border border-[#d7e6d7] bg-[#fbfdf9] p-5">{back}<p className="card-kicker">البطاقة 1 · مصدر الجلسة</p><h2 className="mt-1 text-lg font-black">اختاروا المادة التي سيبني عليها لؤي الاختبار</h2><p className="mt-2 text-xs leading-6 text-[#718078]">يمكنكم إضافة كتاب من «كتبي» أو PDF أو صورة، ودمج المصادر إن أردتم. البحث والسياق والتوقيت اختيارات مساعدة ولا تمنع اكتمال البطاقة.</p></section>;
  const cards: Array<{ step: EngineStep; label: string; title: string; detail: string; ready: boolean; blocked: boolean }> = [{ step: "sources", label: hasSources ? "مكتملة" : "البطاقة 1", title: "مصدر الجلسة", detail: "كتاب من «كتبي» أو PDF أو صورة. دعم البحث والسياق اختياريان.", ready: hasSources, blocked: false }, { step: "prepare", label: bankReady ? "مكتملة" : "البطاقة 2", title: "مراجعة وتحضير لؤي", detail: "توليد بنك موثق من المصدر فقط، بلا رابط أو استعلام يدوي.", ready: bankReady, blocked: !hasSources }, { step: "mode", label: bankReady && mode ? "مكتملة" : "البطاقة 3", title: "اختيار الغرفة", detail: "اختاروا راشد أو الطرف الآخر بعد أن يصبح البنك جاهزاً.", ready: Boolean(bankReady && mode), blocked: !bankReady }];
  return <section className="competition-engine-gateway mb-6"><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><p className="card-kicker">محرك «{engine.title}»</p><h2 className="mt-1 text-xl font-black">ثلاث بطاقات فقط لبدء الجولة</h2><p className="mt-1 max-w-2xl text-xs leading-6 text-[#718078]">افتحوا بطاقة واحدة في كل مرة، والرجوع لا يحذف المصادر أو ما دخلتموه.</p></div><div className="flex gap-2"><button type="button" onClick={onChangeEngine} className="rounded-xl border border-[#dbe4dc] bg-white px-3 py-2 text-xs font-black text-[#52675a]">اختيار محرك آخر</button><button type="button" onClick={onRequestDelete} className="rounded-xl border border-[#efd8d4] bg-[#fff9f8] px-3 py-2 text-xs font-black text-[#a45650]">إدارة الحذف</button></div></div><div className="grid gap-4 lg:grid-cols-3">{cards.map(card => <button key={card.step} type="button" disabled={card.blocked} onClick={() => onOpenStep(card.step)} className={`min-h-52 rounded-[1.5rem] border p-5 text-right transition ${card.ready ? "border-[#b9d9ba] bg-[#f7fcf6]" : card.blocked ? "border-[#e5e7e1] bg-[#fafbf9] opacity-65" : "border-[#d9e6d7] bg-white hover:-translate-y-0.5 hover:border-[#7da47d] hover:shadow-[0_14px_28px_rgba(53,97,64,.09)]"}`}><span className={`inline-flex rounded-lg px-3 py-1.5 text-[11px] font-black ${card.ready ? "bg-[#e4f1e3] text-[#397045]" : "bg-[#f4f6f2] text-[#637168]"}`}>{card.ready ? "✓ " : ""}{card.blocked ? "أكملوا البطاقة السابقة" : card.label}</span><h3 className="mt-4 text-base font-black">{card.title}</h3><p className="mt-2 text-xs leading-6 text-[#718078]">{card.detail}</p></button>)}</div></section>;
}

function CompetitionInvitationMenu({ invitations, open, busy, onOpenChange, onJoin }: { invitations: PendingCompetitionInvitation[]; open: boolean; busy: boolean; onOpenChange: (open: boolean) => void; onJoin: (matchId: number) => void }) {
  if (!invitations.length) return null;
  return <><div className="mb-5 flex justify-end"><button type="button" onClick={() => onOpenChange(true)} className="rounded-xl border border-[#cfdcf0] bg-[#f8faff] px-4 py-2.5 text-xs font-black text-[#426b9d]">دعوات المنافسة ({invitations.length})</button></div><Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-md border-[#dbe2f0] bg-[#fbfcff] text-right"><DialogHeader><p className="card-kicker">دعوات سيف وحنين</p><DialogTitle>اختار الغرفة اللي حابب تدخلها</DialogTitle><DialogDescription className="leading-7">الدعوة اختيارية تماماً. لا تدخل الغرفة ولا تمنعك من منافسة أخرى إلا بعد اختيارك لها.</DialogDescription></DialogHeader><div className="mt-2 space-y-3">{invitations.map(invitation => <article key={invitation.matchId} className="rounded-2xl border border-[#e1e7f2] bg-white p-4"><p className="text-sm font-black">{invitation.engineTitle}</p><p className="mt-1 text-xs leading-6 text-[#738097]">دعوة من {memberLabel(invitation.createdBy)} إلى غرفة سيف وحنين #{invitation.matchId}</p><button type="button" disabled={busy} onClick={() => onJoin(invitation.matchId)} className="mt-3 w-full rounded-xl bg-[#426b9d] px-4 py-3 text-xs font-black text-white disabled:opacity-50">ادخل هذه الغرفة</button></article>)}</div></DialogContent></Dialog></>;
}

function CompetitionOpponentBanner({ match }: { match: CurrentMatch }) {
  const member = useWorkspaceMember();
  const opponent = opponentLabelForMatch(match, member);
  return <section className="page-wrap pt-4"><div className="mx-auto flex max-w-3xl flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#d9e5d8] bg-[#fbfdf9] px-5 py-3"><div><p className="card-kicker">المواجهة الحالية</p><p className="mt-1 text-sm font-black">{member ? `${memberLabel(member)} ضد ${opponent}` : `ضد ${opponent}`}</p></div><span className="rounded-full bg-[#edf5ea] px-3 py-1.5 text-xs font-black text-[#416d50]">خصمك: {opponent}</span></div></section>;
}

function CompetitionLoayReviewPanel({ match }: { match: EvaluatedMatch }) {
  if (!match.loayReview) return null;
  return <section className="page-wrap pt-5"><div className="mx-auto max-w-3xl rounded-[1.45rem] border border-[#d8e7d7] bg-[#f5fbf4] p-5 shadow-[0_12px_28px_rgba(53,104,67,.07)]"><p className="card-kicker text-[#3f704c]">لؤي · التصحيح أمامك</p><h2 className="mt-1 text-lg font-black text-[#315d3f]">التصحيح وخطوة الإصلاح</h2><p className="mt-3 whitespace-pre-wrap text-sm leading-8 text-[#52635a]">{match.loayReview.reviewText}</p></div></section>;
}

function CompetitionRashedCoach({ match, question }: { match: CurrentMatch; question: NonNullable<CurrentMatch["question"]> }) {
  const member = useWorkspaceMember();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState("");
  const [messages, setMessages] = useState<Array<{ role: "user" | "rashed"; content: string }>>([]);
  const [recording, setRecording] = useState(false);
  const [speakReplies, setSpeakReplies] = useState(true);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const recognitionRef = useRef<CompetitionSpeechRecognition | null>(null);
  const speak = (text: string) => { if (!speakReplies || typeof window === "undefined" || !("speechSynthesis" in window)) return; window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text.slice(0, 1200)); utterance.lang = "ar-EG"; utterance.rate = .96; utterance.onstart = () => setIsSpeaking(true); utterance.onend = () => setIsSpeaking(false); utterance.onerror = () => setIsSpeaking(false); window.speechSynthesis.speak(utterance); };
  const coach = trpc.competition.askRashedCoach.useMutation({ onSuccess: result => { setMessages(current => [...current, { role: "rashed", content: result.answer }]); speak(result.answer); }, onError: error => { setMessages(current => current.slice(0, -1)); toast.error(error.message || "راشد مش قادر يناقش السؤال دلوقتي."); } });
  const toggleRecording = () => { if (recording) { recognitionRef.current?.stop(); return; } const speechWindow = window as unknown as { SpeechRecognition?: new () => CompetitionSpeechRecognition; webkitSpeechRecognition?: new () => CompetitionSpeechRecognition };
  const SpeechRecognitionCtor = speechWindow.SpeechRecognition || speechWindow.webkitSpeechRecognition; if (!SpeechRecognitionCtor) { toast.error("المتصفح ده مش بيدعم الإدخال الصوتي؛ اكتب رسالتك بدلاً منه."); return; } const recognition = new SpeechRecognitionCtor(); recognition.lang = "ar-EG"; recognition.interimResults = false; recognition.onresult = event => setDraft(current => `${current} ${event.results?.[0]?.[0]?.transcript || ""}`.trim()); recognition.onerror = () => { setRecording(false); toast.error("ما قدرناش نسمع التسجيل؛ جرّب الكتابة أو اسمح بالميكروفون."); }; recognition.onend = () => { setRecording(false); recognitionRef.current = null; }; recognitionRef.current = recognition; setRecording(true); try { recognition.start(); } catch { setRecording(false); } };
  useEffect(() => () => { recognitionRef.current?.stop(); window.speechSynthesis?.cancel(); }, []);
  const submitCoachMessage = () => { const message = draft.trim(); if (!member || !message || coach.isPending) return; setMessages(current => [...current, { role: "user", content: message }]); setDraft(""); coach.mutate({ memberSlot: member, matchId: match.match.id, matchQuestionId: question.id, message }); };
  if (match.match.mode !== "rashed" || match.match.status !== "question_active") return null;
  return <><button type="button" onClick={() => setOpen(true)} className="competition-rashed-coach-fab" aria-label="افتح نقاش راشد السري حول طريقة الحل"><MessageSquareText size={19} /><span>ناقش راشد</span></button>{open ? <div className="fixed inset-0 z-[240] flex items-end justify-end bg-[#17372c]/35 p-4 backdrop-blur-[2px] sm:p-6" role="dialog" aria-modal="true" aria-label="نقاش راشد السري"><section className="flex max-h-[min(620px,88vh)] w-full max-w-md flex-col overflow-hidden rounded-[1.7rem] border border-[#d4e5d2] bg-[#fffdfa] shadow-2xl" dir="rtl"><header className="flex items-start gap-3 border-b border-[#e5eee2] bg-[#f1f8ef] p-4"><div className="grid size-10 place-items-center rounded-2xl bg-[#315e40] text-white"><Bot size={19} /></div><div className="min-w-0 flex-1"><p className="card-kicker text-[#44734d]">راشد · نقاش سري أثناء الجولة</p><h2 className="mt-1 font-black text-[#2f533b]">نفكّر في السؤال من غير حل</h2><p className="mt-1 text-xs leading-5 text-[#64776a]">راشد ما يشوفش مفتاح الإجابة هنا، ومش هيقول اختياراً أو جواباً نهائياً.</p></div><button type="button" onClick={() => { setOpen(false); recognitionRef.current?.stop(); }} className="rounded-xl px-2 py-1.5 text-xs font-black text-[#617268] hover:bg-white">إغلاق</button></header><div className={"rashed-voice-stage " + (recording ? "is-recording " : "") + (coach.isPending ? "is-listening " : "") + (isSpeaking ? "is-speaking" : "")} role="status" aria-live="polite"><span className="rashed-voice-orbit"><Mic size={16} /></span><div><strong>{recording ? "بنسمعك دلوقتي…" : coach.isPending ? "راشد بيسمع وبيفكر…" : isSpeaking ? "راشد بيتكلم…" : "جاهز نناقش طريقة الحل"}</strong><p>{recording ? "الأذن بتلتقط كلامك؛ اضغط إيقاف التسجيل لما تخلص." : coach.isPending ? "بيجهّز توجيهاً من غير كشف الإجابة." : isSpeaking ? "اسمع رد راشد، والرسالة مكتوبة قدامك كمان." : "اكتب أو اتكلم؛ الصوت ما يغيّرش نتيجة الجولة."}</p></div></div><div className="flex-1 space-y-3 overflow-y-auto p-4">{messages.length ? messages.map((message, index) => <div key={index} className={`max-w-[90%] rounded-2xl px-3 py-2.5 text-sm leading-6 ${message.role === "user" ? "mr-auto bg-[#315e40] text-white" : "border border-[#e3eadf] bg-[#f7faf5] text-[#405648]"}`}><p className="mb-1 text-[10px] font-black opacity-75">{message.role === "user" ? "أنت" : "راشد"}</p>{message.content}</div>) : <div className="rounded-2xl border border-dashed border-[#dbe8d8] bg-[#fbfdf9] p-4 text-sm leading-7 text-[#617369]">اكتب حيرتك أو طريقتك في التفكير. راشد هيسألك سؤال يوجّهك ويقترح طريقة مراجعة، من غير ما يطلع الحل.</div>}{coach.isPending ? <p className="rounded-xl bg-[#fff5df] px-3 py-2 text-xs font-bold text-[#866329]" role="status">راشد بيقرأ طريقة تفكيرك من غير ما يطلع الحل…</p> : null}</div><form onSubmit={event => { event.preventDefault(); submitCoachMessage(); }} className="border-t border-[#e6ece1] bg-white p-3"><textarea value={draft} onChange={event => setDraft(event.target.value)} maxLength={1200} rows={3} className="field-input min-h-20 w-full resize-none text-sm" placeholder="مثال: أنا فاهم إن السؤال بيتكلم عن … بس مش عارف أرتب الفكرة" /><div className="mt-2 flex items-center gap-2"><button type="button" onClick={() => void toggleRecording()} disabled={coach.isPending} className={`inline-flex items-center gap-1.5 rounded-xl px-3 py-2 text-[11px] font-black ${recording ? "bg-[#b34d45] text-white" : "bg-[#f4ead5] text-[#80612e]"}`} aria-label={recording ? "إيقاف الإدخال الصوتي" : "تحدث إلى راشد صوتياً"}>{recording ? <Square size={13} /> : <Mic size={13} />}{recording ? "إيقاف التسجيل" : "تحدث صوتياً"}</button><button type="button" onClick={() => { setSpeakReplies(value => !value); if (speakReplies) window.speechSynthesis?.cancel(); }} className={`inline-flex items-center gap-1.5 rounded-xl px-3 py-2 text-[11px] font-black ${speakReplies ? "bg-[#e6f0e4] text-[#3e6a4c]" : "bg-[#f2f1eb] text-[#7b837d]"}`} aria-pressed={speakReplies} aria-label={speakReplies ? "إيقاف صوت راشد" : "تشغيل صوت راشد"}>{speakReplies ? <Volume2 size={13} /> : <VolumeX size={13} />}{speakReplies ? "صوت راشد مفعّل" : "صوت راشد متوقف"}</button></div><div className="mt-2 flex items-center justify-between gap-3"><p className="text-[10px] leading-5 text-[#748078]">المحادثة لا تسجّل إجابة ولا تغيّر النتيجة.</p><button disabled={!draft.trim() || coach.isPending || !member} className="inline-flex items-center gap-1.5 rounded-xl bg-[#315e40] px-3 py-2 text-xs font-black text-white disabled:opacity-50"><Send size={14} />اسأل راشد</button></div></form></section></div> : null}</>;
}

function CompetitionExamRoom({ match }: { match: CurrentMatch }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const [selectedOption, setSelectedOption] = useState("");
  const [answerText, setAnswerText] = useState("");
  const [matchingAnswers, setMatchingAnswers] = useState<Record<string, string>>({});
  const submit = trpc.competition.submitMatchAnswer.useMutation({ onSuccess: result => { setSelectedOption(""); setAnswerText(""); setMatchingAnswers({}); if (member) void utils.competition.currentMatch.invalidate({ memberSlot: member }); toast.success(result.alreadySubmitted ? "إجابتك كانت متسجلة بالفعل." : "إجابتك اتقفلت بأمان. مستنيين حكم لؤي."); }, onError: error => toast.error(error.message) });
  const question = match.question;
  const opponent = opponentLabelForMatch(match, member);
  const mine = match.answerStates.find(answer => answer.memberSlot === member)?.submitted ?? false;
  useEffect(() => { setSelectedOption(""); setAnswerText(""); setMatchingAnswers({}); }, [question?.id]);
  if (!question) return null;
  const optionBased = question.questionType === "multiple_choice" || question.questionType === "true_false";
  const matchingLeft = question.questionType === "matching" ? question.options.filter(option => option.startsWith("L:")).map(option => option.slice(2).trim()).filter(Boolean) : [];
  const matchingRight = question.questionType === "matching" ? question.options.filter(option => option.startsWith("R:")).map(option => option.slice(2).trim()).filter(Boolean) : [];
  const matchingComplete = matchingLeft.length >= 3 && matchingLeft.every(left => Boolean(matchingAnswers[left]));
  const submitAnswer = (answerText: string) => { if (!member) return; submit.mutate({ memberSlot: member, matchId: match.match.id, matchQuestionId: question.id, answerText, idempotencyKey: typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${match.match.id}-${question.id}-${Date.now()}-answer` }); };
  if (match.match.status === "evaluating") return <section className="page-wrap pt-5"><div className="mx-auto max-w-3xl overflow-hidden rounded-[1.7rem] border border-[#dbe8d8] bg-[#fbfdf9] shadow-[0_20px_48px_rgba(43,94,72,.08)]"><div className="border-b border-[#e4eee1] bg-[#f2f8f0] px-5 py-5"><p className="card-kicker">غرفة الاختبار · الجولة {question.order + 1} · ضد {opponent}</p><h1 className="mt-1 text-xl font-black">لؤي بيحسم الإجابات الآن</h1><p className="mt-2 text-sm leading-7 text-[#66766b]">الإجابات مقفلة، ولا تظهر الإجابة الصحيحة أو نتيجة أي لاعب قبل اكتمال حكم لؤي.</p></div><div className="p-5"><p className="rounded-2xl bg-white p-4 text-sm font-black leading-8 text-[#2f4436]">{question.prompt}</p>{match.match.mode === "rashed" ? <CompetitionRashedPresence match={match} compact /> : null}</div></div></section>;
  return <section className="page-wrap pt-5"><div className="mx-auto max-w-3xl overflow-hidden rounded-[1.7rem] border border-[#dbe8d8] bg-[#fbfdf9] shadow-[0_20px_48px_rgba(43,94,72,.08)]"><div className="border-b border-[#e4eee1] bg-[#f2f8f0] px-5 py-5 sm:px-7"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="card-kicker">غرفة الاختبار · ضد {opponent}</p><h1 className="mt-1 text-xl font-black">السؤال {question.order + 1} من {match.match.questionTotal}</h1><p className="mt-1 text-xs leading-6 text-[#6b7c70]">اختار إجابة واحدة ثم أكدها، أو اكتب إجابتك من لوحة المفاتيح. لا يظهر التصحيح قبل الحسم.</p></div><span className="rounded-full bg-white px-3 py-1.5 text-[11px] font-black text-[#55715e]">{questionTypeLabel[question.questionType] || question.questionType}</span></div></div><div className="p-5 sm:p-7"><article className="rounded-[1.35rem] border border-[#e5ece1] bg-white p-5"><p className="text-lg font-black leading-9 text-[#263c2f]">{question.prompt}</p>{question.imageUrl ? <figure className="mt-4 overflow-hidden rounded-2xl border border-[#dce7d9] bg-[#fbfdf9]"><img src={question.imageUrl} alt="الصورة التعليمية المرتبطة بالسؤال" className="max-h-[360px] w-full object-contain" loading="lazy" /><figcaption className="border-t border-[#edf0ea] px-3 py-2 text-[11px] leading-6 text-[#718078]">الصورة جزء من السؤال؛ مفتاح الإجابة غير ظاهر قبل حكم لؤي.</figcaption></figure> : null}</article>{mine ? <div className="mt-4 rounded-2xl border border-[#d6e9d6] bg-[#f4fbf3] px-4 py-4 text-sm leading-7 text-[#416b4b]">✓ إجابتك اتقفلت بأمان. مستنيين {opponent} أو حكم لؤي، ومش هتظهر إجابتك للخصم قبل النتيجة.</div> : optionBased ? <form onSubmit={event => { event.preventDefault(); if (selectedOption) submitAnswer(selectedOption); }} className="mt-5"><fieldset><legend className="text-sm font-black text-[#3b5543]">اختار إجابة واحدة ثم أكّدها</legend><div role="radiogroup" aria-label="اختيارات السؤال" className="mt-3 grid gap-3">{question.options.map((option, index) => <button key={option} type="button" role="radio" aria-checked={selectedOption === option} onClick={() => setSelectedOption(option)} className={`competition-answer-option ${selectedOption === option ? "is-selected" : ""}`}><span className="competition-answer-radio" aria-hidden="true"><span /></span><span className="competition-answer-letter">{String.fromCharCode(65 + index)}</span><span className="flex-1">{option}</span></button>)}</div></fieldset><button disabled={!member || !selectedOption || submit.isPending} className="mt-4 inline-flex w-full items-center justify-center rounded-2xl bg-[#2d5b4b] px-4 py-3.5 text-sm font-black text-white disabled:opacity-50">{submit.isPending ? "جارٍ حفظ الإجابة…" : "تأكيد الإجابة"}</button></form> : question.questionType === "matching" ? <form onSubmit={event => { event.preventDefault(); if (matchingComplete) submitAnswer(matchingLeft.map(left => `${left}=>${matchingAnswers[left] || ""}`).join("|")); }} className="mt-5 space-y-3"><p className="text-sm font-black text-[#3b5543]">اختار المقابل المناسب لكل عنصر</p>{matchingLeft.map((left, index) => <label key={left} className="grid gap-2 rounded-2xl border border-[#dce7d9] bg-white p-3 sm:grid-cols-[.72fr_1fr] sm:items-center"><span className="text-sm font-black text-[#375245]">{index + 1}. {left}</span><select value={matchingAnswers[left] || ""} onChange={event => setMatchingAnswers(current => ({ ...current, [left]: event.target.value }))} className="field-input text-sm" disabled={submit.isPending}><option value="">اختار المقابل…</option>{matchingRight.map(right => <option key={right} value={right}>{right}</option>)}</select></label>)}<button disabled={!member || !matchingComplete || submit.isPending} className="w-full rounded-2xl bg-[#2d5b4b] px-4 py-3.5 text-sm font-black text-white disabled:opacity-50">تأكيد إجابات التوصيل</button></form> : <form onSubmit={event => { event.preventDefault(); if (answerText.trim()) submitAnswer(answerText.trim()); }} className="mt-5"><label className="block text-sm font-black text-[#3b5543]">اكتب إجابتك</label><p className="mt-1 text-xs leading-6 text-[#748078]">اكتب بطريقتك حتى لو بالعامية المصرية؛ لؤي يراجع المعنى والفكرة الأساسية لا التطابق الحرفي، وصياغتك تظل مخفية عن {opponent} أثناء الجولة.</p><textarea value={answerText} onChange={event => setAnswerText(event.target.value)} maxLength={1800} rows={5} className="field-input mt-3 min-h-32 w-full resize-y" placeholder="اكتب إجابتك هنا…" /><button disabled={!member || !answerText.trim() || submit.isPending} className="mt-3 w-full rounded-2xl bg-[#2d5b4b] px-4 py-3.5 text-sm font-black text-white disabled:opacity-50">{submit.isPending ? "جارٍ حفظ الإجابة…" : "تأكيد الإجابة المكتوبة"}</button></form>}<CompetitionRationaleBox match={match} />{match.match.mode === "rashed" ? <><CompetitionRashedCoach match={match} question={question} /><div className="mt-5"><CompetitionRashedPresence match={match} compact /></div></> : null}</div></div></section>;
}

function CompetitionConnectionNotice({ match, browserOnline, connectionRestored }: { match: CurrentMatch; browserOnline: boolean; connectionRestored: boolean }) {
  if (browserOnline && !connectionRestored) return null;
  if (!browserOnline) return <section role="alert" aria-live="assertive" className="ai-alert-enter mb-5 rounded-[1.45rem] border border-[#ead4a6] bg-[#fffaf0] p-5 text-[#705a2c]"><p className="card-kicker text-[#946b31]">الاتصال بالمباراة</p><h2 className="mt-1 text-lg font-black">الاتصال بالإنترنت انقطع مؤقتاً.</h2><p className="mt-2 text-sm leading-7">تقدمكم محفوظ في الغرفة الخادمية؛ مش هنلغي المباراة ولا نعيد السؤال. أول ما الشبكة ترجع، هنحدّث آخر حالة تلقائياً.</p></section>;
  return <section role="status" aria-live="polite" className="ai-alert-enter mb-5 rounded-[1.45rem] border border-[#cfe4d0] bg-[#f5fcf4] p-5 text-[#3d7048]"><p className="card-kicker text-[#4a8151]">الاتصال رجع</p><h2 className="mt-1 text-lg font-black">رجع الاتصال — بنستعيد آخر حالة محفوظة.</h2><p className="mt-2 text-sm leading-7">الغرفة والأسئلة والإجابات المقفولة ما زالت كما هي، وتقدروا تكملوا من نفس المكان.</p></section>;
}

function CompetitionDisconnectNotice({ match }: { match: CurrentMatch }) {
  const disconnectedPlayers = match.players.filter(player => player.state === "disconnected");
  const names = disconnectedPlayers.map(player => memberLabel(player.memberSlot)).join(" و");
  return <section role="status" aria-live="polite" className="mb-5 rounded-[1.45rem] border border-[#ead4a6] bg-[#fffaf0] p-5 text-[#705a2c]"><p className="card-kicker text-[#946b31]">حالة الاتصال</p><h2 className="mt-1 text-lg font-black">الاتصال انقطع عند {names}، مستنيين يرجع.</h2><p className="mt-2 text-sm leading-7">الغرفة والأسئلة اللي اتفتحت محفوظة؛ الانقطاع ما بيلغيش المباراة ولا بيعيد السؤال. لما يرجع اللاعب، الخادم يرجّعه لنفس حالة الغرفة.</p>{match.question?.deadlineAt ? <p className="mt-2 text-xs leading-6 text-[#87692f]">المؤقت الخادمي للسؤال ما زال شغال عشان تفضل الجولة عادلة للطرفين.</p> : null}</section>;
}

function CompetitionWebSourcePicker({ engineId, member, enabled, onAdded }: { engineId: number | null; member: Member | null; enabled: boolean; onAdded: () => void }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<WebSourceResult[]>([]);
  const search = trpc.competition.searchWebSources.useMutation({ onSuccess: sources => { setResults(sources as WebSourceResult[]); toast.success("راجعنا المصادر المتاحة. اختاروا مصدراً واحداً لإضافته للمحرك."); }, onError: error => toast.error(error.message || "البحث مش متاح دلوقتي.") });
  const add = trpc.competition.addWebSource.useMutation({ onSuccess: () => { setResults([]); setQuery(""); onAdded(); toast.success("اتحفظ مصدر الويب بلقطة موثقة داخل المحرك."); }, onError: error => toast.error(error.message || "ما قدرناش نضيف المصدر ده.") });
  if (!engineId) return null;
  return <section className="mb-5 rounded-[1.4rem] border border-[#dfe9db] bg-[#f8fcf6] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="card-kicker">مصدر ويب مساعد</p><h2 className="text-base font-black">ابحثوا ثم اختاروا مصدر موثق للمحرك</h2><p className="mt-1 text-xs leading-6 text-[#718078]">المصدر المختار فقط بيتسحب محتواه ويتحفظ كلقطة. ما بنمررش رابط مكتوب مباشرة للؤي ولا بنضيف نتائج تلقائياً.</p></div><Sparkles className="text-[#a67839]" size={20} /></div><form onSubmit={event => { event.preventDefault(); if (query.trim().length < 2) return; search.mutate({ query: query.trim() }); }} className="mt-4 flex gap-2"><input value={query} onChange={event => setQuery(event.target.value)} maxLength={300} className="field-input min-w-0 flex-1" placeholder="مثال: منهج فيزياء الصف الثاني البكالوريا وزارة التعليم" /><button disabled={!enabled || query.trim().length < 2 || search.isPending || add.isPending} className="rounded-xl bg-[#2d5b4b] px-4 text-xs font-black text-white disabled:opacity-50">{search.isPending ? "بنبحث…" : "بحث موثوق"}</button></form>{results.length ? <div className="mt-4 space-y-2">{results.map(source => <article key={source.url} className="rounded-xl border border-[#e1ebde] bg-white p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="font-black">{source.title}</p>{source.official ? <span className="rounded-full bg-[#e5f2e2] px-2 py-0.5 text-[10px] font-black text-[#397145]">رسمي</span> : null}</div><p className="mt-1 line-clamp-2 text-xs leading-6 text-[#728079]">{source.snippet}</p><a href={source.url} target="_blank" rel="noreferrer" className="mt-1 inline-block max-w-full truncate text-[11px] font-bold text-[#52735b] underline">{source.url}</a></div><button type="button" disabled={!enabled || !member || add.isPending} onClick={() => add.mutate({ memberSlot: member!, engineId, query, sourceUrl: source.url })} className="shrink-0 rounded-lg bg-[#edf5ea] px-3 py-2 text-xs font-black text-[#3c704a] disabled:opacity-50">اختيار المصدر</button></div></article>)}</div> : null}</section>;
}

function CompetitionAutomaticWebResearchPanel({ engineId, member, researches }: { engineId: number | null; member: Member | null; researches: AutomaticWebResearch[] }) {
  const [readerSourceId, setReaderSourceId] = useState<number | null>(null);
  const reader = trpc.competition.automaticWebReader.useQuery({ memberSlot: member ?? "saif", engineId: engineId ?? 1, sourceId: readerSourceId ?? 1 }, { enabled: Boolean(member && engineId && readerSourceId) });
  const items = researches;
  const source = reader.data as AutomaticWebReader | undefined;
  if (!engineId || !items.length) return null;
  return <><section className="mb-5 rounded-[1.4rem] border border-[#e8dfc7] bg-[#fffdf7] p-5"><div><p className="card-kicker">لؤي بحث تلقائياً</p><h2 className="text-base font-black">شوفوا ماذا بحث وماذا اختار</h2><p className="mt-1 text-xs leading-6 text-[#718078]">الكتاب يظل مرجع المحرك الأساسي. هنا تظهر عبارة البحث والنتائج التي فُحصت، والمصدر الذي حُفظ كمساعد فقط.</p></div><div className="mt-4 space-y-4">{items.map(run => <article key={run.id} className="overflow-hidden rounded-2xl border border-[#eee5d2] bg-white"><div className="border-b border-[#f1eadc] px-4 py-3"><p className="text-xs font-black text-[#87682e]">بحث من: {run.sourceLabel}</p><p className="mt-1 text-sm font-bold">{run.query}</p></div><div className="divide-y divide-[#f3eee4]">{run.results.map(result => { const selected = run.selected?.sourceUrl === result.url; return <div key={result.url} className="flex flex-wrap items-start gap-3 px-4 py-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-black">{result.title}</p>{result.official ? <span className="rounded-full bg-[#e5f2e2] px-2 py-0.5 text-[10px] font-black text-[#397145]">رسمي</span> : null}{selected ? <span className="rounded-full bg-[#fff0cd] px-2 py-0.5 text-[10px] font-black text-[#936927]">اختاره لؤي</span> : null}</div><p className="mt-1 text-xs leading-6 text-[#718078]">{result.snippet}</p></div>{selected ? <button type="button" onClick={() => setReaderSourceId(run.selectedSourceId)} className="shrink-0 rounded-xl bg-[#f4ecd9] px-3 py-2 text-[11px] font-black text-[#805f27]">فتح داخل المنصة</button> : null}</div>; })}</div></article>)}</div></section><Dialog open={readerSourceId !== null} onOpenChange={open => { if (!open) setReaderSourceId(null); }}><DialogContent className="max-h-[88vh] max-w-4xl overflow-hidden bg-[#fffdfa] text-right"><DialogHeader><DialogTitle>{source?.label || "المصدر المختار"}</DialogTitle><DialogDescription>{source?.sourceUrl || "جارٍ تحميل المصدر الموثق…"}</DialogDescription></DialogHeader><div className="mt-3 max-h-[60vh] overflow-y-auto rounded-xl border border-[#eee7da] bg-white p-4"><pre dir="rtl" className="whitespace-pre-wrap font-sans text-sm leading-8 text-[#445249]">{reader.isLoading ? "بنفتح المصدر…" : source?.contentSnapshot || "تعذر عرض محتوى المصدر حالياً."}</pre></div></DialogContent></Dialog></>;
}

function CompetitionSourceInsightsPanel({ engineId, member, disabled, onUpdated }: { engineId: number | null; member: Member | null; disabled: boolean; onUpdated: () => void }) {
  const insights = trpc.competition.sourceInsights.useQuery({ engineId: engineId ?? 1 }, { enabled: engineId !== null, refetchInterval: 15_000 });
  const analyze = trpc.competition.analyzeSources.useMutation({ onSuccess: () => { onUpdated(); toast.success("اتحللت المصادر من لقطاتها الموثقة."); }, onError: error => toast.error(error.message || "تحليل المصادر مش متاح دلوقتي.") });
  const data = (insights.data ?? []) as SourceInsight[];
  if (!engineId) return null;
  return <section className="mb-5 rounded-[1.4rem] border border-[#eee4cb] bg-[#fffdf6] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="card-kicker">خريطة المحتوى</p><h2 className="text-base font-black">موضوعات ومفاهيم من المصادر</h2><p className="mt-1 text-xs leading-6 text-[#718078]">ابدأوا التحليل صراحةً، وكل موضوع أو مفهوم ظاهر تحته دليل من لقطة المصدر نفسها.</p></div><button type="button" disabled={!member || disabled || analyze.isPending} onClick={() => analyze.mutate({ memberSlot: member!, engineId })} className="rounded-xl bg-[#fbf0dc] px-4 py-2.5 text-xs font-black text-[#8f6530] disabled:opacity-50">{analyze.isPending ? "لؤي بيحلل…" : data.length ? "تحديث التحليل" : "تحليل المصادر"}</button></div>{data.length ? <div className="mt-4 space-y-3">{data.map(insight => <article key={insight.sourceId} className="rounded-2xl border border-[#efe7d3] bg-white p-4"><p className="font-black">{insight.sourceLabel}</p>{insight.topics.length ? <div className="mt-3 flex flex-wrap gap-2">{insight.topics.map(topic => <span key={`${topic.title}-${topic.evidenceQuote}`} className="rounded-full bg-[#fff5e1] px-2.5 py-1 text-[11px] font-bold text-[#88672f]" title={topic.evidenceQuote}>{topic.title}</span>)}</div> : null}{insight.concepts.length ? <div className="mt-3 space-y-2">{insight.concepts.slice(0, 5).map(concept => <div key={`${concept.term}-${concept.evidenceQuote}`} className="rounded-xl bg-[#fbfaf7] p-3"><p className="text-xs font-black">{concept.term}</p><p className="mt-1 text-xs leading-6 text-[#627066]">{concept.explanation}</p><p className="mt-2 border-r-2 border-[#d7b977] pr-2 text-[11px] leading-5 text-[#8a7351]">«{concept.evidenceQuote}»</p></div>)}</div> : <p className="mt-3 text-xs text-[#77847b]">مفيش مفاهيم مدعومة بدليل كفاية في اللقطة دي.</p>}</article>)}</div> : <p className="mt-4 text-xs leading-6 text-[#77847b]">لسه مفيش تحليل محفوظ. لن يتولد أو يُحفظ أي محتوى قبل الضغط على «تحليل المصادر».</p>}</section>;
}

function CompetitionPdfPageSourcePicker({ engineId, member, enabled, onAdded }: { engineId: number | null; member: Member | null; enabled: boolean; onAdded: () => void }) {
  const sourceOptions = trpc.competition.sourceOptions.useQuery();
  const [fileId, setFileId] = useState("");
  const [pageStart, setPageStart] = useState("");
  const [pageEnd, setPageEnd] = useState("");
  const options = (sourceOptions.data ?? { notes: [], files: [] }) as SourceOptions;
  const file = options.files.find(item => item.id === Number(fileId));
  const rangeIsPartial = Boolean(pageStart) !== Boolean(pageEnd);
  const rangeIssue = !file ? null : rangeIsPartial ? "اكتبوا أول وآخر صفحة معاً، أو سيبوا الحقلين فاضيين لاستخدام الكتاب كله." : pageStart && pageEnd && Number(pageEnd) < Number(pageStart) ? "نطاق الصفحات لازم يبدأ من رقم أقل أو يساوي صفحة النهاية." : pageStart && pageEnd && file.pageCount && Number(pageEnd) > file.pageCount ? `الكتاب ده آخره صفحة ${file.pageCount}.` : null;
  const add = trpc.competition.addStudyFileSource.useMutation({ onSuccess: () => { setFileId(""); setPageStart(""); setPageEnd(""); onAdded(); toast.success("اتحفظت صفحات الكتاب المختارة فقط كمصدر للمحرك."); }, onError: error => toast.error(error.message || "ما قدرناش نضيف نطاق الصفحات ده.") });
  if (!engineId) return null;
  return <section className="mb-5 rounded-[1.4rem] border border-[#dce8e8] bg-[#f7fcfc] p-5"><div><p className="card-kicker">كتاب من «كتبي» ونطاق صفحات</p><h2 className="text-base font-black">اختاروا كتابكم المحفوظ أو حددوا صفحاته</h2><p className="mt-1 text-xs leading-6 text-[#718078]">ده مسار كتاب محفوظ مسبقاً في «كتبي». تقدروا تسيبوا الصفحات فاضية فيعتمد المحرك على النص المفهرس كله، أو تحددوا نطاقاً دقيقاً. الصفحات المصوّرة من غير نص هتحتاج OCR بدل ما نتخيل محتواها.</p></div><div className="mt-4 grid gap-2 sm:grid-cols-[1fr_.45fr_.45fr_auto]"><select value={fileId} onChange={event => { setFileId(event.target.value); setPageStart(""); setPageEnd(""); }} disabled={!enabled || add.isPending} className="field-input text-xs"><option value="">اختاروا كتاب PDF مفهرس</option>{options.files.map(item => <option key={item.id} value={item.id}>{item.subjectName || "كتاب"} · {item.label}{item.pageCount ? ` (${item.pageCount} صفحة)` : ""}</option>)}</select><input inputMode="numeric" value={pageStart} onChange={event => setPageStart(event.target.value.replace(/\D/g, ""))} disabled={!enabled || add.isPending} className="field-input" placeholder="من صفحة (اختياري)" /><input inputMode="numeric" value={pageEnd} onChange={event => setPageEnd(event.target.value.replace(/\D/g, ""))} disabled={!enabled || add.isPending} className="field-input" placeholder="إلى صفحة (اختياري)" /><button type="button" disabled={!enabled || !member || !fileId || add.isPending || Boolean(rangeIssue)} onClick={() => add.mutate({ memberSlot: member!, engineId, fileId: Number(fileId), pageStart: pageStart ? Number(pageStart) : undefined, pageEnd: pageEnd ? Number(pageEnd) : undefined })} className="rounded-xl bg-[#e3f1f0] px-4 py-2.5 text-xs font-black text-[#386d6b] disabled:opacity-50">{add.isPending ? "بنجهّز الكتاب…" : pageStart ? "إضافة النطاق" : "استخدام الكتاب كله"}</button></div>{file ? <div role="status" className="mt-3 rounded-xl bg-white/80 px-3 py-2 text-xs leading-6 text-[#6c7b78]"><p>{file.hasPageIndex ? "فهرس الصفحات جاهز." : "هنجهّز فهرس الصفحات من الكتاب مرة واحدة عند الإضافة."}{file.pageCount ? ` إجمالي الكتاب: ${file.pageCount} صفحة.` : ""}</p>{rangeIssue ? <p className="mt-1 font-bold text-[#a26047]">{rangeIssue}</p> : pageStart && pageEnd ? <p className="mt-1 font-bold text-[#396b68]">لؤي هيعتمد على الصفحات {pageStart}–{pageEnd} فقط.</p> : <p className="mt-1">لو سيبتوا الحقلين فاضيين، لؤي هيعتمد على النص المفهرس من الكتاب كله.</p>}</div> : null}</section>;
}

function CompetitionUploadedPdfSourcePicker({ engineId, member, enabled, onAdded }: { engineId: number | null; member: Member | null; enabled: boolean; onAdded: () => void }) {
  const [label, setLabel] = useState("");
  const [fileName, setFileName] = useState("");
  const [dataBase64, setDataBase64] = useState("");
  const [pageStart, setPageStart] = useState("");
  const [pageEnd, setPageEnd] = useState("");
  const [uploadNotice, setUploadNotice] = useState<string | null>(null);
  const add = trpc.competition.addUploadedPdfSource.useMutation({ onSuccess: () => { setLabel(""); setFileName(""); setDataBase64(""); setPageStart(""); setPageEnd(""); setUploadNotice(null); onAdded(); toast.success("اتحفظ الكتاب داخل المحرك كلقطة مصدر موثقة."); }, onError: error => toast.error(error.message || "ما قدرناش نضيف الكتاب للمحرك.") });
  if (!engineId) return null;
  const rangeIsPartial = Boolean(pageStart) !== Boolean(pageEnd);
  const rangeStatus = rangeIsPartial ? "اكتب رقم بداية ونهاية معاً، أو سيب الحقلين فاضيين." : pageStart && pageEnd ? `لؤي هيقرأ الصفحات ${pageStart}–${pageEnd} فقط بعد ما الخادم يتحقق من النص.` : "من غير نطاق، لؤي هيستخدم النص المقروء المتاح من الكتاب كله.";
  return <section className="mb-5 rounded-[1.4rem] border border-[#dbe7ef] bg-[#f8fbff] p-5"><div><p className="card-kicker">PDF مرفوع مباشرة للمحرك</p><h2 className="text-base font-black">ارفعوا PDF خاص للجولة دي</h2><p className="mt-1 text-xs leading-6 text-[#718078]">ده مسار رفع مستقل للمحرك؛ مش بيضيف الكتاب لمكتبتكم. استخدموا PDF قابل للبحث حتى 30 ميغابايت؛ لو الصفحات صور من غير نص، أضيفوها كصور OCR بدل ما لؤي يخمن المحتوى.</p></div><div className="mt-4 grid gap-2 sm:grid-cols-2"><input value={label} onChange={event => setLabel(event.target.value)} maxLength={300} disabled={!enabled || add.isPending} className="field-input" placeholder="اسم يظهر داخل المحرك (اختياري)" /><input type="file" accept="application/pdf,.pdf" disabled={!enabled || add.isPending} onChange={async event => { const file = event.target.files?.[0]; if (!file) return; if ((file.type && file.type !== "application/pdf") || !/\.pdf$/i.test(file.name) || file.size > 30 * 1024 * 1024) { event.target.value = ""; setFileName(""); setDataBase64(""); setUploadNotice("اختاروا ملف PDF حتى 30 ميغابايت."); return toast.error("اختاروا ملف PDF حتى 30 ميغابايت."); } try { setUploadNotice(null); setFileName(file.name); setDataBase64(await readImageAsDataUrl(file)); } catch (error) { const message = error instanceof Error ? error.message : "تعذر قراءة الكتاب."; setUploadNotice(message); toast.error(message); } }} className="field-input text-xs" /><input inputMode="numeric" value={pageStart} onChange={event => setPageStart(event.target.value.replace(/\D/g, ""))} disabled={!enabled || add.isPending} className="field-input" placeholder="من صفحة (اختياري)" /><input inputMode="numeric" value={pageEnd} onChange={event => setPageEnd(event.target.value.replace(/\D/g, ""))} disabled={!enabled || add.isPending} className="field-input" placeholder="إلى صفحة (اختياري)" /></div><div role="status" className="mt-3 rounded-xl bg-white/80 px-3 py-2 text-xs leading-6 text-[#6d7a78]">{uploadNotice ? <p className="font-bold text-[#a26047]">{uploadNotice}</p> : <p>{fileName ? `الكتاب المختار: ${fileName}.` : "اختاروا PDF من جهازكم؛ لا يتحفظ في «كتبي»."} <span className={rangeIsPartial ? "font-black text-[#a26047]" : "font-bold text-[#42628a]"}>{rangeStatus}</span></p>}</div><div className="mt-3 flex flex-wrap items-center justify-end gap-3"><button type="button" disabled={!enabled || !member || !fileName || !dataBase64 || rangeIsPartial || add.isPending} onClick={() => add.mutate({ memberSlot: member!, engineId, label: label.trim() || undefined, fileName, dataBase64, pageStart: pageStart ? Number(pageStart) : undefined, pageEnd: pageEnd ? Number(pageEnd) : undefined })} className="rounded-xl bg-[#e7effa] px-4 py-2.5 text-xs font-black text-[#42628a] disabled:opacity-50">{add.isPending ? "بنقرأ الكتاب…" : "إضافة كتاب للمحرك"}</button></div></section>;
}

function CompetitionImageSourcePicker({ engineId, member, enabled, onAdded }: { engineId: number | null; member: Member | null; enabled: boolean; onAdded: () => void }) {
  const [label, setLabel] = useState("");
  const [imageName, setImageName] = useState("");
  const [mimeType, setMimeType] = useState<"image/jpeg" | "image/png" | "image/webp" | null>(null);
  const [dataBase64, setDataBase64] = useState("");
  const add = trpc.competition.addImageSource.useMutation({ onSuccess: () => { setLabel(""); setImageName(""); setMimeType(null); setDataBase64(""); onAdded(); toast.success("اتقرت الصورة واتحفظ النص الموثق كمصدر للمحرك."); }, onError: error => toast.error(error.message || "الصورة ما اتضافتش كمصدر.") });
  if (!engineId) return null;
  return <section className="mb-5 rounded-[1.4rem] border border-[#e8dce9] bg-[#fdf9fd] p-5"><div><p className="card-kicker">صورة تعليمية OCR</p><h2 className="text-base font-black">اقرؤوا صورة ثم استخدموا نصها فقط</h2><p className="mt-1 text-xs leading-6 text-[#718078]">ارفعوا صفحة أو ورقة تعليمية واضحة. لؤي يقرأ النص الظاهر، ولو القراءة ضعيفة يوقف الإضافة بدل ما يخمّن المحتوى.</p></div><div className="mt-4 grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><input value={label} onChange={event => setLabel(event.target.value)} maxLength={300} disabled={!enabled || add.isPending} className="field-input" placeholder="اسم المصدر (اختياري)" /><input type="file" accept="image/jpeg,image/png,image/webp" disabled={!enabled || add.isPending} onChange={async event => { const file = event.target.files?.[0]; if (!file) return; if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 8 * 1024 * 1024) { event.target.value = ""; return toast.error("اختاروا JPG أو PNG أو WEBP حتى 8 ميغابايت."); } try { setImageName(file.name); setMimeType(file.type as "image/jpeg" | "image/png" | "image/webp"); setDataBase64(await readImageAsDataUrl(file)); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر قراءة الصورة."); } }} className="field-input text-xs" /><button type="button" disabled={!enabled || !member || !imageName || !mimeType || !dataBase64 || add.isPending} onClick={() => add.mutate({ memberSlot: member!, engineId, label: label.trim(), imageName, mimeType: mimeType!, dataBase64 })} className="rounded-xl bg-[#f3e8f4] px-4 py-2.5 text-xs font-black text-[#80558a] disabled:opacity-50">{add.isPending ? "لؤي بيقرأ…" : "قراءة وإضافة الصورة"}</button></div>{imageName ? <p className="mt-3 text-xs leading-6 text-[#776d7a]">الصورة المختارة: {imageName}. لن تحفظ كمصدر أسئلة إلا لو خرج OCR بنص مقروء بثقة كافية.</p> : null}</section>;
}

function CompetitionEngineContextPicker({ engine, member, disabled, onUpdated }: { engine: EngineDetail | undefined; member: Member | null; disabled: boolean; onUpdated: () => void }) {
  const [subjectName, setSubjectName] = useState(engine?.subjectName ?? "");
  const [gradeLevel, setGradeLevel] = useState(engine?.gradeLevel ?? "");
  const [unitName, setUnitName] = useState(engine?.unitName ?? "");
  const [lessonTitle, setLessonTitle] = useState(engine?.lessonTitle ?? "");
  const update = trpc.competition.updateEngineContext.useMutation({ onSuccess: () => { onUpdated(); toast.success("اتحفظ سياق المنهج للمحرك."); }, onError: error => toast.error(error.message || "ما قدرناش نحفظ السياق دلوقتي.") });
  if (!engine) return null;
  return <section className="mb-5 rounded-[1.4rem] border border-[#e1e8ef] bg-[#f9fbff] p-5"><div><p className="card-kicker">سياق المنهج</p><h2 className="text-base font-black">خلّوا لؤي يعرف نطاق الأسئلة</h2><p className="mt-1 text-xs leading-6 text-[#718078]">السياق يوجّه اختيار الأسئلة من اللقطات اللي تحددوها، ولا يضيف معلومة من خارج المصدر.</p></div><form onSubmit={event => { event.preventDefault(); if (!member) return; update.mutate({ memberSlot: member, engineId: engine.id, subjectName: subjectName.trim() || undefined, gradeLevel: gradeLevel.trim() || undefined, unitName: unitName.trim() || undefined, lessonTitle: lessonTitle.trim() || undefined }); }} className="mt-4 grid gap-2 sm:grid-cols-2"><input value={subjectName} onChange={event => setSubjectName(event.target.value)} maxLength={120} disabled={disabled || update.isPending} className="field-input" placeholder="المادة: فيزياء مثلاً" /><input value={gradeLevel} onChange={event => setGradeLevel(event.target.value)} maxLength={64} disabled={disabled || update.isPending} className="field-input" placeholder="الصف أو المسار" /><input value={unitName} onChange={event => setUnitName(event.target.value)} maxLength={180} disabled={disabled || update.isPending} className="field-input" placeholder="الوحدة (اختياري)" /><input value={lessonTitle} onChange={event => setLessonTitle(event.target.value)} maxLength={240} disabled={disabled || update.isPending} className="field-input" placeholder="الدرس (اختياري)" /><button disabled={!member || disabled || update.isPending} className="sm:col-span-2 rounded-xl bg-[#e7effa] px-4 py-2.5 text-xs font-black text-[#42628a] disabled:opacity-50">{update.isPending ? "جارٍ الحفظ…" : "حفظ سياق المحرك"}</button></form>{disabled ? <p className="mt-3 text-xs leading-6 text-[#8a7253]">بعد تجهيز البنك يقفل السياق لحماية اتساق الأسئلة مع المصدر.</p> : null}</section>;
}

function CompetitionPageLegacy() {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const engines = trpc.competition.listEngines.useQuery();
  const sourceOptions = trpc.competition.sourceOptions.useQuery();
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [enginePendingDeletion, setEnginePendingDeletion] = useState<Pick<Engine, "id" | "title"> | null>(null);
  const detail = trpc.competition.getEngine.useQuery({ id: selectedId ?? 1 }, { enabled: selectedId !== null, refetchInterval: 5_000 });
  const questions = trpc.competition.listQuestions.useQuery({ engineId: selectedId ?? 1 }, { enabled: selectedId !== null, refetchInterval: 5_000 });
  const activeMatch = trpc.competition.currentMatch.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 4_000 });
  const pendingInvitationsQuery = trpc.competition.pendingInvitations.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 8_000 });
  const [title, setTitle] = useState("");
  const [questionCount, setQuestionCount] = useState("8");
  const [difficulty, setDifficulty] = useState("2");
  const [questionTimeLimitSeconds, setQuestionTimeLimitSeconds] = useState("0");
  const [noteId, setNoteId] = useState("");
  const [fileId, setFileId] = useState("");
  const [textLabel, setTextLabel] = useState("");
  const [textContent, setTextContent] = useState("");
  const [answerText, setAnswerText] = useState("");
  const [matchingAnswers, setMatchingAnswers] = useState<Record<string, string>>({});
  const [browserOnline, setBrowserOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [connectionRestored, setConnectionRestored] = useState(false);
  const [activeEngineStep, setActiveEngineStep] = useState<EngineStep | null>(null);
  const [competitionMode, setCompetitionMode] = useState<CompetitionMode | null>(null);
  const [invitationsOpen, setInvitationsOpen] = useState(false);

  const selected = detail.data as EngineDetail | undefined;
  const currentEngines = (engines.data ?? []) as Engine[];
  const options = (sourceOptions.data ?? { notes: [], files: [] }) as SourceOptions;
  const bank = (questions.data ?? []) as CompetitionQuestion[];
  const match = activeMatch.data as CurrentMatch | null | undefined;
  const pendingInvitations = (pendingInvitationsQuery.data ?? []) as PendingCompetitionInvitation[];
  const automaticResearchQuery = trpc.competition.automaticWebResearches.useQuery({ memberSlot: member ?? "saif", engineId: selectedId ?? 1 }, { enabled: Boolean(member && selectedId), refetchInterval: 8_000 });
  const automaticResearches = (automaticResearchQuery.data ?? []) as AutomaticWebResearch[];
  const sourceInsightsQuery = trpc.competition.sourceInsights.useQuery({ engineId: selectedId ?? 1 }, { enabled: Boolean(selectedId), refetchInterval: 12_000 });
  const sourceInsights = (sourceInsightsQuery.data ?? []) as SourceInsight[];
  const refreshAutomaticResearch = trpc.competition.refreshAutomaticWebResearch.useMutation({ onSuccess: () => { if (member && selectedId) void utils.competition.automaticWebResearches.invalidate({ memberSlot: member, engineId: selectedId }); void invalidate(); toast.success("لؤي بدأ أو حدّث البحث المساعد من المصادر المختارة."); }, onError: error => toast.error(error.message || "البحث المساعد لم يكتمل حالياً.") });
  const selectedLabel = useMemo(() => currentEngines.find(engine => engine.id === selectedId)?.title, [currentEngines, selectedId]);
  const refreshMatch = async () => { if (member) await utils.competition.currentMatch.invalidate({ memberSlot: member }); };
  useEffect(() => { setActiveEngineStep(null); setCompetitionMode(null); }, [selectedId]);
  useEffect(() => {
    const handleOffline = () => { setBrowserOnline(false); setConnectionRestored(false); };
    const handleOnline = () => {
      setBrowserOnline(true);
      setConnectionRestored(true);
      void refreshMatch();
      window.setTimeout(() => setConnectionRestored(false), 4_500);
    };
    window.addEventListener("offline", handleOffline);
    window.addEventListener("online", handleOnline);
    return () => { window.removeEventListener("offline", handleOffline); window.removeEventListener("online", handleOnline); };
  }, [member]);
  useEffect(() => {
    const hideLegacyTextSource = () => {
      document.querySelectorAll<HTMLTextAreaElement>('textarea[placeholder="الصق محتوى الدرس أو التعليمات…"]').forEach(textarea => {
        textarea.closest("div.rounded-2xl")?.setAttribute("hidden", "");
      });
    };
    hideLegacyTextSource();
    const observer = new MutationObserver(hideLegacyTextSource);
    observer.observe(document.body, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, [selectedId]);
  const invalidate = async () => {
    await Promise.all([
      utils.competition.listEngines.invalidate(),
      selectedId ? utils.competition.getEngine.invalidate({ id: selectedId }) : Promise.resolve(),
      selectedId ? utils.competition.listQuestions.invalidate({ engineId: selectedId }) : Promise.resolve(),
      member && selectedId ? utils.competition.automaticWebResearches.invalidate({ memberSlot: member, engineId: selectedId }) : Promise.resolve(),
      refreshMatch(),
    ]);
  };

  const createMutation = trpc.competition.createEngine.useMutation({ onSuccess: engine => { setTitle(""); setSelectedId(engine?.id ?? null); void invalidate(); toast.success("اتعمل محرك جديد. ضيفوا له مصادر الدراسة الأول."); }, onError: error => toast.error(error.message || "ما قدرناش نعمل المحرك دلوقتي.") });
  const create = { ...createMutation, mutate: (input: { memberSlot: Member; title: string; questionCount: number; difficulty: number }) => createMutation.mutate({ ...input, questionTimeLimitSeconds: Number(questionTimeLimitSeconds) as 0 | 30 | 60 | 90 | 120 }) };
  const addNote = trpc.competition.addNoteSource.useMutation({ onSuccess: () => { setNoteId(""); void invalidate(); toast.success("اتضافت الملاحظة كمصدر للجولة."); }, onError: error => toast.error(error.message) });
  const addFile = trpc.competition.addStudyFileSource.useMutation({ onSuccess: () => { setFileId(""); void invalidate(); toast.success("اتضاف الكتاب المفهرس كمصدر للجولة."); }, onError: error => toast.error(error.message) });
  const addText = trpc.competition.addTextSource.useMutation({ onSuccess: () => { setTextLabel(""); setTextContent(""); void invalidate(); toast.success("اتضاف النص كمصدر للجولة."); }, onError: error => toast.error(error.message) });
  const setPrimaryMutation = trpc.competition.setPrimarySource.useMutation({ onSuccess: () => { void invalidate(); toast.success("اتحدد المصدر الأساسي للمحرك."); }, onError: error => toast.error(error.message || "ما قدرناش نغيّر أولوية المصدر.") });
  const setPrimary = { ...setPrimaryMutation, mutate: (input: { memberSlot: Member; engineId: number | null; sourceId: number }) => { if (input.engineId) setPrimaryMutation.mutate({ ...input, engineId: input.engineId }); } };
  const remove = trpc.competition.removeSource.useMutation({ onSuccess: () => { void invalidate(); toast.success("اتشال المصدر من المحرك."); }, onError: error => toast.error(error.message) });
  const deleteEngine = trpc.competition.deleteEngine.useMutation({ onSuccess: () => { const deletedId = enginePendingDeletion?.id; setEnginePendingDeletion(null); if (selectedId === deletedId) setSelectedId(null); void invalidate(); toast.success("اتحذف المحرك من القائمة، وسجل المنافسات والإنجازات فضل محفوظ."); }, onError: error => toast.error(error.message || "المحرك ما اتحذفش.") });
  const generate = trpc.competition.generateQuestions.useMutation({ onSuccess: result => { void invalidate(); const warning = result.warnings?.[0] ? ` ${result.warnings[0]}` : ""; toast.success(`اتجهز ${result.acceptedCount} سؤال موثق${result.partial ? ` من أصل ${result.requestedCount} مطلوب` : ""}.${warning}`); }, onError: error => toast.error(error.message || "لؤي ما قدرش يجهز بنك الأسئلة دلوقتي.") });
  const analyzeSources = trpc.competition.analyzeSources.useMutation({ onSuccess: () => { if (selectedId) void utils.competition.sourceInsights.invalidate({ engineId: selectedId }); toast.success("لؤي خلّص قراءة وفهم المصادر وبدأ بناء البنك تلقائياً."); if (member && selectedId) generate.mutate({ memberSlot: member, engineId: selectedId }); }, onError: error => { if (selectedId) void utils.competition.sourceInsights.invalidate({ engineId: selectedId }); toast.warning("لؤي استخدم فهم النص الأصلي، وهيك يقدر يكمل بناء البنك بدون ما يوقف."); if (member && selectedId) generate.mutate({ memberSlot: member, engineId: selectedId }); } });
  const confirmQuestionBank = trpc.competition.confirmQuestionBank.useMutation({ onSuccess: () => { void invalidate(); toast.success("اتعتمد بنك الأسئلة واتقفل للمنافسة."); }, onError: error => toast.error(error.message || "ما قدرناش نقفل بنك الأسئلة.") });
  const questionProgressQuery = trpc.competition.questionProgress.useQuery({ engineId: selectedId ?? 1 }, { enabled: Boolean(selectedId), refetchInterval: generate.isPending ? 700 : false });
  const questionProgress = questionProgressQuery.data as CompetitionQuestionProgress | undefined;
  const createMatch = trpc.competition.createMatch.useMutation({ onSuccess: () => { void refreshMatch(); toast.success("الغرفة اتفتحت. مستنيين الطرف التاني يدخل."); }, onError: error => toast.error(error.message) });
  const createRashedMatch = trpc.competition.createRashedMatch.useMutation({ onSuccess: () => { void refreshMatch(); toast.success("بدأت مواجهتك ضد راشد. رده متقفل لحد ما لؤي يحسم الجولة."); }, onError: error => toast.error(error.message) });
  const joinMatch = trpc.competition.joinMatch.useMutation({ onSuccess: () => { setInvitationsOpen(false); void refreshMatch(); if (member) void utils.competition.pendingInvitations.invalidate({ memberSlot: member }); toast.success("دخلت الغرفة. لما تبقى جاهز دوس «أنا جاهز»."); }, onError: error => toast.error(error.message) });
  const readyMatch = trpc.competition.readyMatch.useMutation({ onSuccess: () => { void refreshMatch(); toast.success("اتسجلت جاهزيتك."); }, onError: error => toast.error(error.message) });
  const submitAnswer = trpc.competition.submitMatchAnswer.useMutation({ onSuccess: result => { setAnswerText(""); setMatchingAnswers({}); void refreshMatch(); if (result.alreadySubmitted) toast.success("إجابتك كانت متسجلة بالفعل."); else toast.success("إجابتك اتقفلت بأمان. مستنيين الطرف التاني."); }, onError: error => toast.error(error.message) });
  const busy = create.isPending || addNote.isPending || addFile.isPending || addText.isPending || setPrimary.isPending || remove.isPending || deleteEngine.isPending || generate.isPending || analyzeSources.isPending || confirmQuestionBank.isPending || refreshAutomaticResearch.isPending || createMatch.isPending || createRashedMatch.isPending || joinMatch.isPending || readyMatch.isPending || submitAnswer.isPending;
  const canGenerate = Boolean(selected && selected.status === "draft" && selected.sources.length && member);
  const prepareQuestions = () => {
    if (!member || !selectedId) return;
    if (!sourceInsights.length) {
      analyzeSources.mutate({ memberSlot: member, engineId: selectedId });
      return;
    }
    if (bank.length) {
      toast.info("راجع بنك الأسئلة الظاهر أسفل الصفحة ثم اعتمده قبل بدء المنافسة.");
      return;
    }
    generate.mutate({ memberSlot: member, engineId: selectedId });
  };
  const myPlayer = match?.players.find(player => player.memberSlot === member);
  const myAnswerSubmitted = match?.answerStates.find(answer => answer.memberSlot === member)?.submitted ?? false;
  const optionBased = match?.question?.questionType === "multiple_choice" || match?.question?.questionType === "true_false";
  const matchingLeft = match?.question?.questionType === "matching" ? match.question.options.filter(option => option.startsWith("L:")).map(option => option.slice(2).trim()).filter(Boolean) : [];
  const matchingRight = match?.question?.questionType === "matching" ? match.question.options.filter(option => option.startsWith("R:")).map(option => option.slice(2).trim()).filter(Boolean) : [];
  const matchingComplete = matchingLeft.length >= 3 && matchingLeft.every(left => Boolean(matchingAnswers[left]));
  const matchingAnswerText = matchingLeft.map(left => `${left}=>${matchingAnswers[left] || ""}`).join("|");

  return <div className="page-wrap" data-competition-layout={selected && !match ? activeEngineStep ?? "cards" : "full"}>
    <div className="competition-page-tools" aria-label="إعدادات المنافسة"><CompetitionSoundToggle /><span>تقدروا تكتموا المؤثرات من هنا، والحركة البصرية هتفضل موجودة.</span></div>
    <AlertDialog open={Boolean(enginePendingDeletion)} onOpenChange={open => { if (!open && !deleteEngine.isPending) setEnginePendingDeletion(null); }}>
      <AlertDialogContent className="border-[#eadfd5] bg-[#fffdfa] text-right">
        <AlertDialogHeader>
          <p className="card-kicker">إدارة المحرك</p>
          <AlertDialogTitle>حذف المحرك؟</AlertDialogTitle>
          <AlertDialogDescription className="leading-7">{enginePendingDeletion ? `سيُحذف محرك «${enginePendingDeletion.title}» من قائمة المحركات. لو له جلسات منتهية، سجل المنافسات والإنجازات ونتائج الجولات هيفضلوا محفوظين باسم المحرك. لا يمكن حذف محرك مربوط بمباراة شغالة.` : ""}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={deleteEngine.isPending}>إلغاء</AlertDialogCancel>
          <AlertDialogAction disabled={!member || deleteEngine.isPending || !enginePendingDeletion} onClick={() => { if (member && enginePendingDeletion) deleteEngine.mutate({ memberSlot: member, engineId: enginePendingDeletion.id }); }} className="bg-[#a95550] hover:bg-[#934843]">{deleteEngine.isPending ? "جارٍ الحذف…" : "حذف المحرك"}</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
    <header className="mb-8"><p className="eyebrow">لؤي · منافسة تعليمية</p><h1 className="page-title">تنافس</h1><p className="mt-2 max-w-3xl text-sm leading-7 text-[#748078]">ابنوا محرك الجولة من ملاحظاتكم وكتبكم ونصوصكم. لؤي هيلتزم بالمصادر اللي بتختاروها، والغرفة ما بتبدأش إلا لما سيف وحنين يدخلوا ويعلنوا الجاهزية.</p></header>
    <CompetitionEngineMotion engine={selected} match={match} busy={busy} showRashedCue={competitionMode === "rashed" || match?.match.mode === "rashed"} />
    {selectedId && questionProgress && questionProgress.status !== "idle" ? <CompetitionQuestionProgressPanel progress={questionProgress} /> : null}
    {selected && selected.status === "draft" && !match ? <CompetitionUnderstandingPanel insights={sourceInsights} busy={analyzeSources.isPending} onAnalyze={() => { if (member && selectedId) analyzeSources.mutate({ memberSlot: member, engineId: selectedId }); }} /> : null}
    {selected && selected.status === "draft" && bank.length && !match ? <CompetitionQuestionReviewPanel questions={bank} busy={confirmQuestionBank.isPending} onConfirm={() => { if (member && selectedId) confirmQuestionBank.mutate({ memberSlot: member, engineId: selectedId }); }} /> : null}
    <CompetitionLocalSimulation />
    {!match ? <CompetitionInvitationMenu invitations={pendingInvitations} open={invitationsOpen} busy={busy} onOpenChange={setInvitationsOpen} onJoin={matchId => { if (member) joinMatch.mutate({ memberSlot: member, matchId }); }} /> : null}
    {match ? <CompetitionConnectionNotice match={match} browserOnline={browserOnline} connectionRestored={connectionRestored} /> : null}
    {match ? <CompetitionRationaleBox match={match} /> : null}
    {match ? <CompetitionPreparationFlow engine={selected} match={match} member={member} busy={busy} preparing={generate.isPending || analyzeSources.isPending} automaticResearches={automaticResearches} researchesLoading={automaticResearchQuery.isLoading} onPrepare={prepareQuestions} onStart={() => { if (member && selectedId) createMatch.mutate({ memberSlot: member, engineId: selectedId }); }} onStartRashed={() => { if (member && selectedId) createRashedMatch.mutate({ memberSlot: member, engineId: selectedId }); }} onJoin={() => { if (member && match) joinMatch.mutate({ memberSlot: member, matchId: match.match.id }); }} onReady={() => { if (member && match) readyMatch.mutate({ memberSlot: member, matchId: match.match.id }); }} /> : selected ? <CompetitionEngineGateway engine={selected} activeStep={activeEngineStep} mode={competitionMode} busy={busy} preparing={generate.isPending || analyzeSources.isPending} onOpenStep={setActiveEngineStep} onBack={() => setActiveEngineStep(null)} onModeChange={setCompetitionMode} onPrepare={prepareQuestions} onStartDuel={() => { if (member && selectedId) createMatch.mutate({ memberSlot: member, engineId: selectedId }); }} onStartRashed={() => { if (member && selectedId) createRashedMatch.mutate({ memberSlot: member, engineId: selectedId }); }} onChangeEngine={() => setSelectedId(null)} onRequestDelete={() => setEnginePendingDeletion(selected)} /> : null}
    {match?.match.mode === "rashed" ? <CompetitionRashedPresence match={match} /> : null}
    <section className="mb-5 rounded-[1.35rem] border border-[#dce8e8] bg-[#f7fcfc] p-5"><p className="card-kicker">مصدر الجلسة</p><h2 className="mt-1 text-base font-black">اختاروا كتباً أو PDF أو صوراً — وامزجوهم لو تحبوا</h2><p className="mt-1 text-xs leading-6 text-[#718078]">مصدر الجلسة هو الكتاب من «كتبي» و/أو PDF من جهازكم و/أو صورة تعليمية ترفعونها. بعد الاختيار يستخرج لؤي موضوع البحث من هذه المواد نفسها؛ لا تكتبوا له رابطاً أو مصدر بحث يدوياً.</p>{selected?.sources.length ? <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#e7ddd0] bg-white/80 p-3"><p className="text-xs leading-6 text-[#65736b]">{automaticResearches.length ? `تم حفظ ${automaticResearches.length} بحث مساعد قابل للمراجعة. تقدروا تحدثوه من نفس المصادر.` : "الكتب والملفات المختارة هي المرجع الأساسي. ابدأوا البحث المساعد لتوسيع التحقق قبل تجهيز البنك."}</p><button type="button" disabled={!member || selected.status !== "draft" || Boolean(match) || refreshAutomaticResearch.isPending} onClick={() => { if (member && selectedId) refreshAutomaticResearch.mutate({ memberSlot: member, engineId: selectedId }); }} className="shrink-0 rounded-xl bg-[#89652f] px-4 py-2.5 text-xs font-black text-white disabled:opacity-50">{refreshAutomaticResearch.isPending ? "لؤي بيبحث…" : automaticResearches.length ? "تحديث البحث المساعد" : "بدء البحث المساعد"}</button></div> : null}</section>
    <section className="mb-5 flex flex-wrap items-center justify-between gap-4 rounded-[1.35rem] border border-[#d9e6d7] bg-[#f8fcf6] px-5 py-4"><div><p className="card-kicker">مؤقت السؤال</p><h2 className="text-base font-black">إعداد المحرك الجديد</h2><p className="mt-1 text-xs leading-6 text-[#718078]">المؤقت اختياري ومفروض من الخادم عند تفعيل السؤال؛ لو انتهى الوقت قبل الإرسال، تتسجل حالة غياب بلا نقاط.</p></div><select value={questionTimeLimitSeconds} onChange={event => setQuestionTimeLimitSeconds(event.target.value)} className="field-input w-full sm:w-48"><option value="0">من غير مؤقت</option><option value="30">30 ثانية لكل سؤال</option><option value="60">دقيقة لكل سؤال</option><option value="90">دقيقة ونصف لكل سؤال</option><option value="120">دقيقتان لكل سؤال</option></select></section>
    <CompetitionUploadedPdfSourcePicker engineId={selectedId} member={member} enabled={Boolean(selected && selected.status === "draft" && !match)} onAdded={() => { void invalidate(); }} />
    <CompetitionPdfPageSourcePicker engineId={selectedId} member={member} enabled={Boolean(selected && selected.status === "draft" && !match)} onAdded={() => { void invalidate(); }} />
    <CompetitionImageSourcePicker engineId={selectedId} member={member} enabled={Boolean(selected && selected.status === "draft" && !match)} onAdded={() => { void invalidate(); }} />
    <details className="mb-5 rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] px-5 py-3"><summary className="cursor-pointer text-sm font-black text-[#53685a]">تحقق ومراجعة اختيارية</summary><p className="mt-2 text-xs leading-6 text-[#77847b]">البحث يبدأ من مصادر الجلسة المختارة فوق. هنا فقط تراجعوا نتائجه أو تضيفون سياق المنهج لتحسين نوع الأسئلة؛ ليس مطلوباً كتابة مصدر بحث.</p><div className="mt-4"><CompetitionEngineContextPicker key={selected?.id ?? "context"} engine={selected} member={member} disabled={Boolean(selected && (selected.status !== "draft" || match))} onUpdated={() => { void invalidate(); }} /><CompetitionSourceInsightsPanel engineId={selectedId} member={member} disabled={Boolean(match)} onUpdated={() => { void invalidate(); }} /><CompetitionAutomaticWebResearchPanel engineId={selectedId} member={member} researches={automaticResearches} /></div></details>
    {selected?.sources.length ? <section className="mb-5 overflow-hidden rounded-[1.4rem] border border-[#e1eadd] bg-[#fbfdf9] shadow-[0_12px_30px_rgba(43,94,72,.05)]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e7eee4] px-5 py-4"><div><p className="card-kicker">أولوية المصادر</p><h2 className="text-base font-black">مين المرجع الأساسي؟</h2><p className="mt-1 text-xs leading-6 text-[#718078]">لؤي يخصّص غالبية أسئلة البنك للمصدر الأساسي، وتكمّل المصادر المساعدة الباقي.</p></div><Star className="text-[#b48338]" size={20} fill="currentColor" /></div><div className="divide-y divide-[#edf1eb]">{selected.sources.map(source => { const sourceTypeLabel = source.sourceType === "lesson_note" ? "ملاحظة درس" : source.sourceType === "study_file" ? `${source.sourceRefId ? "من كتبي · " : "كتاب خاص مرفوع · "}PDF${source.pageStart ? ` · صفحات ${source.pageStart}–${source.pageEnd}` : " مفهرس"}` : source.sourceType === "url" ? "مصدر ويب موثّق" : source.sourceType === "image" ? "صورة مقروءة OCR" : "نص مضاف يدويًا"; return <div key={`priority-${source.id}`} className="flex flex-wrap items-center gap-3 px-5 py-3.5"><div className={`grid size-9 place-items-center rounded-xl ${source.isPrimary ? "bg-[#fff0cd] text-[#9b6e26]" : "bg-[#edf2eb] text-[#65806a]"}`}><Star size={16} fill={source.isPrimary ? "currentColor" : "none"} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-black">{source.label}</p><p className="mt-1 text-[11px] text-[#758179]">{sourceTypeLabel}{source.isPrimary ? " · المرجع المعتمد أولاً" : " · مصدر مساعد"}</p></div>{source.isPrimary ? <span className="rounded-full bg-[#fff1d3] px-3 py-1.5 text-[11px] font-black text-[#94692d]">المصدر الأساسي</span> : <button type="button" disabled={selected.status !== "draft" || !member || busy || Boolean(match)} onClick={() => setPrimary.mutate({ memberSlot: member!, engineId: selectedId, sourceId: source.id })} className="inline-flex items-center gap-1.5 rounded-xl border border-[#d8e4d6] bg-white px-3 py-2 text-[11px] font-black text-[#416b4b] transition hover:bg-[#edf5ea] disabled:opacity-50"><Star size={14} />اختاره أساسي</button>}</div>; })}</div>{selected.status !== "draft" ? <p className="border-t border-[#e7eee4] px-5 py-3 text-xs leading-6 text-[#78857c]">اتقفل ترتيب الأولوية بعد تجهيز البنك لحماية اتساق الأسئلة والمباراة.</p> : null}</section> : null}
    {selected && !match ? <div className="mb-5 flex justify-end"><button type="button" disabled={!member || busy} onClick={() => setEnginePendingDeletion(selected)} className="rounded-xl border border-[#f0d8d4] bg-[#fff8f7] px-4 py-2.5 text-xs font-black text-[#a65450] disabled:opacity-50">حذف المحرك المحدد</button></div> : null}
    {match ? <section className="mb-5 overflow-hidden rounded-[1.6rem] border border-[#d7e8d8] bg-[#f8fcf6] shadow-[0_18px_45px_rgba(43,94,72,.08)]"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-[#e1ede0] px-5 py-5 sm:px-7"><div className="flex items-start gap-3"><div className="icon-tile bg-[#dfeee0] text-[#35714a]"><UsersRound size={20} /></div><div><p className="card-kicker">غرفة منافسة حقيقية</p><h2 className="text-xl font-black">{roomStatusLabel[match.match.status]}</h2><p className="mt-1 text-xs leading-6 text-[#6d7b70]">الحالة بتتحدّث من الخادم كل شوية. الإجابات مش بتظهر للطرف التاني قبل مرحلة التقييم.</p></div></div><span className="rounded-full bg-white px-3 py-1.5 text-xs font-black text-[#497054]">مباراة #{match.match.id}</span></div><div className="grid gap-4 p-5 sm:p-7 lg:grid-cols-[.35fr_1fr]"><div className="space-y-2">{match.players.map(player => <div key={player.memberSlot} className="flex items-center justify-between rounded-xl bg-white px-3 py-2.5 text-xs"><span className="font-black">{memberLabel(player.memberSlot)}{player.memberSlot === member ? " (أنت)" : ""}</span><span className={`font-bold ${player.state === "ready" ? "text-[#3e7a4f]" : player.state === "invited" ? "text-[#a66f2d]" : "text-[#708077]"}`}>{player.state === "ready" ? "جاهز" : player.state === "joined" ? "دخل الغرفة" : player.state === "invited" ? "لسه ما دخلش" : player.state}</span></div>)}</div><div>{match.match.status === "waiting" && myPlayer?.state === "invited" ? <button type="button" disabled={busy || !member} onClick={() => joinMatch.mutate({ memberSlot: member!, matchId: match.match.id })} className="inline-flex items-center gap-2 rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50"><UsersRound size={16} />ادخل الغرفة</button> : null}{["waiting", "ready"].includes(match.match.status) && myPlayer && myPlayer.state !== "invited" && myPlayer.state !== "ready" ? <button type="button" disabled={busy || !member} onClick={() => readyMatch.mutate({ memberSlot: member!, matchId: match.match.id })} className="inline-flex items-center gap-2 rounded-xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50"><CheckCircle2 size={16} />أنا جاهز</button> : null}{["waiting", "ready"].includes(match.match.status) && myPlayer?.state === "ready" ? <p className="rounded-xl bg-white px-4 py-3 text-sm leading-7 text-[#607266]">جاهزيتك اتسجلت. مستنيين اللاعب التاني يكمل دخوله وجاهزيته.</p> : null}{match.match.status === "question_active" && match.question ? <div><div className="mb-3 flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#e7f1e5] px-2 py-1 text-[10px] font-black text-[#3f724e]">السؤال {match.question.order + 1} من {match.match.questionTotal}</span><span className="rounded-full bg-[#fff3df] px-2 py-1 text-[10px] font-black text-[#956b36]">{questionTypeLabel[match.question.questionType] || match.question.questionType}</span><span className="inline-flex items-center gap-1 text-[11px] font-bold text-[#77847b]"><Timer size={13} />مفيش مؤقت مفروض في النسخة دي</span></div><p className="text-base font-black leading-8 text-[#263c2f]">{match.question.prompt}</p>{match.question.imageUrl ? <figure className="mt-4 overflow-hidden rounded-2xl border border-[#dce7d9] bg-white"><img src={match.question.imageUrl} alt="الصورة التعليمية المرتبطة بالسؤال" className="max-h-[360px] w-full object-contain" loading="lazy" /><figcaption className="border-t border-[#edf0ea] px-3 py-2 text-[11px] leading-6 text-[#718078]">الصورة هي مصدر السؤال المختار؛ الإجابة المعتمدة لا تظهر هنا.</figcaption></figure> : null}{myAnswerSubmitted ? <div className="mt-4 rounded-2xl bg-white px-4 py-3 text-sm leading-7 text-[#51705a]"><LockKeyhole className="ml-2 inline size-4" />إجابتك اتقفلت، ومش هتظهر للطرف التاني. مستنيين إجابته.</div> : optionBased ? <div className="mt-4 grid gap-2 sm:grid-cols-2">{match.question.options.map(option => <button type="button" key={option} disabled={busy || !member} onClick={() => submitAnswer.mutate({ memberSlot: member!, matchId: match.match.id, matchQuestionId: match.question!.id, answerText: option, idempotencyKey: typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${match.match.id}-${match.question!.id}-${Date.now()}-answer` })} className="rounded-2xl border border-[#dce7d9] bg-white px-4 py-3 text-right text-sm font-bold text-[#375245] transition hover:border-[#66936d] hover:bg-[#f5faf3] disabled:opacity-50">{option}</button>)}</div> : match.question.questionType === "matching" ? <form onSubmit={event => { event.preventDefault(); if (!member || !matchingComplete) return; submitAnswer.mutate({ memberSlot: member, matchId: match.match.id, matchQuestionId: match.question!.id, answerText: matchingAnswerText, idempotencyKey: typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${match.match.id}-${match.question!.id}-${Date.now()}-matching` }); }} className="mt-4 space-y-3"><p className="text-xs leading-6 text-[#718078]">اختاروا المقابل المناسب لكل عنصر. اختياركم بيتقفل عند الإرسال ومش بيتشاف للطرف التاني.</p>{matchingLeft.map((left, index) => <label key={left} className="grid gap-2 rounded-xl border border-[#dce7d9] bg-white p-3 sm:grid-cols-[.72fr_1fr] sm:items-center"><span className="text-sm font-black text-[#375245]">{index + 1}. {left}</span><select value={matchingAnswers[left] || ""} onChange={event => setMatchingAnswers(current => ({ ...current, [left]: event.target.value }))} className="field-input text-sm" disabled={busy}><option value="">اختاروا المقابل…</option>{matchingRight.map(right => <option key={right} value={right}>{right}</option>)}</select></label>)}<button disabled={busy || !member || !matchingComplete} className="inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50"><Send size={17} />إرسال التوصيل</button></form> : <form onSubmit={event => { event.preventDefault(); if (!member || !answerText.trim()) return; submitAnswer.mutate({ memberSlot: member, matchId: match.match.id, matchQuestionId: match.question!.id, answerText: answerText.trim(), idempotencyKey: typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${match.match.id}-${match.question!.id}-${Date.now()}-answer` }); }} className="mt-4 flex gap-2"><textarea value={answerText} onChange={event => setAnswerText(event.target.value)} maxLength={1800} rows={3} className="field-input min-h-16 flex-1 resize-none" placeholder="اكتب إجابتك، ومحدش هيشوفها قبل التقييم…" /><button disabled={busy || !answerText.trim() || !member} className="grid size-12 shrink-0 place-items-center rounded-2xl bg-[#2d5b4b] text-white disabled:opacity-50" aria-label="إرسال الإجابة"><Send size={17} /></button></form>}</div> : null}{match.match.status === "evaluating" ? <div className="rounded-2xl bg-white px-4 py-4 text-sm leading-7 text-[#536a59]"><Sparkles className="ml-2 inline size-4 text-[#a67839]" />وصلت الإجابتين واتقفلت. مرحلة التقييم الدلالي والنقاط هتظهر في الخطوة الجاية من النظام، والإجابات لسه مخفية عن الطرفين.</div> : null}</div></div></section> : null}
    <section className="grid gap-5 xl:grid-cols-[.42fr_1fr]"><aside className="space-y-5"><section className="surface-card p-5"><div className="flex items-center gap-3"><div className="icon-tile bg-[#fff0db] text-[#a66f2d]"><Trophy size={19} /></div><div><p className="card-kicker">محرك جديد</p><h2 className="text-lg font-black">اختاروا موضوع المنافسة</h2></div></div><form onSubmit={event => { event.preventDefault(); if (!member) return toast.error("اختار هويتك الأول."); create.mutate({ memberSlot: member, title: title.trim(), questionCount: Number(questionCount), difficulty: Number(difficulty) }); }} className="mt-5 space-y-3"><input value={title} onChange={event => setTitle(event.target.value)} maxLength={240} className="field-input w-full" placeholder="مثال: منافسة قوانين الحركة" /><div className="grid grid-cols-2 gap-2"><select value={questionCount} onChange={event => setQuestionCount(event.target.value)} className="field-input"><option value="5">5 أسئلة</option><option value="8">8 أسئلة</option><option value="12">12 سؤال</option><option value="16">16 سؤال</option></select><select value={difficulty} onChange={event => setDifficulty(event.target.value)} className="field-input">{[1, 2, 3, 4].map(value => <option key={value} value={value}>{difficultyLabel(value)}</option>)}</select></div><button disabled={!member || title.trim().length < 2 || busy || Boolean(match)} className="inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50"><Plus size={17} />إنشاء المحرك</button>{match ? <p className="text-xs leading-6 text-[#8a7253]">إضافة محرك جديد متوقفة مؤقتاً لحد ما المباراة الشغالة تخلص.</p> : null}</form></section><section className="surface-card overflow-hidden"><div className="border-b border-[#edf0ea] px-5 py-4"><p className="card-kicker">محركاتكم</p><h2 className="text-lg font-black">اختاروا محرك للتجهيز أو احذفوه</h2></div>{engines.isLoading ? <div className="h-40 animate-pulse bg-[#f5f4ef]" /> : currentEngines.length ? <div className="divide-y divide-[#edf0ea]">{currentEngines.map(engine => <div key={engine.id} className={`flex items-center gap-2 p-2 transition ${engine.id === selectedId ? "bg-[#edf5ea]" : "hover:bg-[#fbfcf9]"}`}><button type="button" onClick={() => setSelectedId(engine.id)} className="min-w-0 flex-1 p-2 text-right"><div className="flex items-center justify-between gap-3"><p className="truncate text-sm font-black">{engine.title}</p><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-[#7a6348]">{engine.status === "ready" ? "جاهز" : `${engine.sourceCount} مصادر`}</span></div><p className="mt-1 text-xs text-[#748078]">{engine.subjectName || "مادة غير محددة"} · {engine.questionCount} أسئلة · {difficultyLabel(engine.difficulty)}</p></button><button type="button" disabled={!member || busy} onClick={event => { event.stopPropagation(); setEnginePendingDeletion(engine); }} className="grid size-10 shrink-0 place-items-center rounded-xl border border-[#f0d8d4] bg-[#fff8f7] text-[#a65450] transition hover:bg-[#fff0ee] disabled:opacity-50" aria-label={`حذف المحرك ${engine.title}`} title="حذف المحرك نهائياً"><Trash2 size={17} /></button></div>)}</div> : <p className="p-5 text-sm leading-7 text-[#77847b]">اعملوا أول محرك، وبعدها اختاروا بالضبط المصادر اللي لؤي يبني منها المنافسة.</p>}</section></aside><main className="space-y-5">{selectedId && selected ? <><section className="surface-card p-5 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">المحرك المحدد</p><h2 className="mt-1 text-2xl font-black">{selected.title}</h2><p className="mt-2 text-sm text-[#748078]">{selected.sources.length} مصادر متاحة · {selected.questionCount} أسئلة مستهدفة · مستوى {difficultyLabel(selected.difficulty)}</p></div><span className={`rounded-2xl px-3 py-2 text-xs font-black ${selected.status === "ready" ? "bg-[#e6f0e3] text-[#376a4a]" : "bg-[#f7edd8] text-[#9a6d34]"}`}>{selected.status === "ready" ? "بنك الأسئلة جاهز" : "مرحلة تجهيز المصادر"}</span></div><div className="mt-5 rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-black">بنك الأسئلة الموثّق</p><p className="mt-1 text-xs leading-6 text-[#77847b]">لن يبدأ التوليد إلا من اللقطات اللي اخترتوها. الأسئلة غير المدعومة بدليل مطابق للمصدر مش بتتحفظ.</p></div>{selected.status === "draft" ? <button type="button" disabled={!canGenerate || busy || Boolean(match)} onClick={() => generate.mutate({ memberSlot: member!, engineId: selectedId })} className="inline-flex items-center gap-2 rounded-xl bg-[#2d5b4b] px-4 py-2.5 text-xs font-black text-white disabled:opacity-50"><Sparkles size={15} />{generate.isPending ? "لؤي بيجهّز البنك…" : "توليد البنك"}</button> : <span className="inline-flex items-center gap-1.5 text-xs font-black text-[#3f7250]"><CheckCircle2 size={16} />{bank.length} أسئلة محفوظة</span>}</div>{selected.status === "draft" && !selected.sources.length ? <p className="mt-3 text-xs leading-6 text-[#a46854]">ضيفوا مصدراً واحداً على الأقل عشان زر التوليد يشتغل.</p> : null}</div>{selected.status === "ready" ? <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-[#eef5ec] p-4"><div><p className="text-sm font-black text-[#315d3f]">جاهزين تفتحوا غرفة الجولة؟</p><p className="mt-1 text-xs leading-6 text-[#5f7566]">سيف وحنين لازم يدخلوا ويعلنوا الجاهزية قبل ما يظهر أول سؤال.</p></div><button type="button" disabled={!member || busy || Boolean(match)} onClick={() => createMatch.mutate({ memberSlot: member!, engineId: selectedId })} className="inline-flex items-center gap-2 rounded-xl bg-[#2d5b4b] px-4 py-2.5 text-xs font-black text-white disabled:opacity-50"><CircleDot size={15} />فتح غرفة الجولة</button></div> : null}<div className="mt-6 grid gap-3 lg:grid-cols-3"><div className="rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] p-4"><div className="flex items-center gap-2 text-[#416d50]"><BookOpen size={16} /><p className="text-xs font-black">ملاحظة درس</p></div><select value={noteId} onChange={event => setNoteId(event.target.value)} className="field-input mt-3 w-full text-xs"><option value="">اختاروا ملاحظة مكتوبة</option>{options.notes.map(note => <option key={note.id} value={note.id}>{note.subjectName} · {note.label}</option>)}</select><button type="button" disabled={selected.status !== "draft" || !member || !noteId || busy || Boolean(match)} onClick={() => addNote.mutate({ memberSlot: member!, engineId: selectedId, noteId: Number(noteId) })} className="mt-3 w-full rounded-xl bg-[#e6f0e3] px-3 py-2 text-xs font-black text-[#376a4a] disabled:opacity-50">إضافة للمحرك</button></div><div className="rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] p-4"><div className="flex items-center gap-2 text-[#946b31]"><FileText size={16} /><p className="text-xs font-black">كتاب PDF مفهرس</p></div><select value={fileId} onChange={event => setFileId(event.target.value)} className="field-input mt-3 w-full text-xs"><option value="">اختاروا كتاب جاهز للبحث</option>{options.files.map(file => <option key={file.id} value={file.id}>{file.subjectName || "كتاب"} · {file.label}</option>)}</select><button type="button" disabled={selected.status !== "draft" || !member || !fileId || busy || Boolean(match)} onClick={() => addFile.mutate({ memberSlot: member!, engineId: selectedId, fileId: Number(fileId) })} className="mt-3 w-full rounded-xl bg-[#fbf0dc] px-3 py-2 text-xs font-black text-[#8f6530] disabled:opacity-50">إضافة للمحرك</button></div><div className="rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] p-4"><div className="flex items-center gap-2 text-[#5c6592]"><Sparkles size={16} /><p className="text-xs font-black">نص أو تعليمات</p></div><input value={textLabel} onChange={event => setTextLabel(event.target.value)} maxLength={300} className="field-input mt-3 w-full text-xs" placeholder="اسم المصدر" /><textarea value={textContent} onChange={event => setTextContent(event.target.value)} maxLength={120000} rows={3} className="field-input mt-2 w-full resize-none text-xs" placeholder="الصق محتوى الدرس أو التعليمات…" /><button type="button" disabled={selected.status !== "draft" || !member || textLabel.trim().length < 2 || textContent.trim().length < 20 || busy || Boolean(match)} onClick={() => addText.mutate({ memberSlot: member!, engineId: selectedId, label: textLabel.trim(), content: textContent.trim() })} className="mt-3 w-full rounded-xl bg-[#eceef9] px-3 py-2 text-xs font-black text-[#53618d] disabled:opacity-50">إضافة للمحرك</button></div></div></section><section className="surface-card overflow-hidden"><div className="flex items-center justify-between gap-3 border-b border-[#edf0ea] px-5 py-4"><div><p className="card-kicker">مصادر الجولة</p><h2 className="text-lg font-black">لؤي هيلتزم بالمصادر دي</h2></div><Layers3 className="text-[#a67839]" size={20} /></div>{selected.sources.length ? <div className="divide-y divide-[#edf0ea]">{selected.sources.map(source => <article key={source.id} className="flex items-center gap-3 p-4"><div className="grid size-10 place-items-center rounded-2xl bg-[#f4f1e7] text-[#846638]">{source.sourceType === "lesson_note" ? <BookOpen size={17} /> : source.sourceType === "study_file" ? <FileText size={17} /> : <Sparkles size={17} />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-black">{source.label}</p><p className="mt-1 text-[11px] text-[#77847b]">{source.sourceType === "lesson_note" ? "ملاحظة درس محفوظة" : source.sourceType === "study_file" ? "كتاب PDF مفهرس" : "نص مضاف يدويًا"}</p></div><button type="button" onClick={() => remove.mutate({ memberSlot: member!, engineId: selectedId, sourceId: source.id })} disabled={selected.status !== "draft" || !member || busy || Boolean(match)} className="grid size-9 place-items-center rounded-xl text-[#a55d57] hover:bg-[#fff0ee] disabled:opacity-50" aria-label="إزالة المصدر"><Trash2 size={16} /></button></article>)}</div> : <div className="p-8 text-center"><Layers3 className="mx-auto size-9 text-[#aab8ad]" /><h3 className="mt-3 font-black">المحرك لسه من غير محتوى</h3><p className="mt-2 text-sm leading-6 text-[#77847b]">أضيفوا ملاحظة أو كتاب مفهرس أو نص. مش هنبدأ توليد أسئلة قبل وجود مصدر حقيقي.</p></div>}</section>{selected.status === "ready" ? <section className="surface-card overflow-hidden"><div className="border-b border-[#edf0ea] px-5 py-4"><p className="card-kicker">معاينة البنك</p><h2 className="text-lg font-black">أسئلة محفوظة بدليلها</h2></div>{questions.isLoading ? <div className="h-24 animate-pulse bg-[#f5f4ef]" /> : bank.length ? <div className="divide-y divide-[#edf0ea]">{bank.map((question, index) => <article key={question.id} className="p-5"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#edf5ea] px-2 py-1 text-[10px] font-black text-[#3d704d]">{questionTypeLabel[question.questionType] || question.questionType}</span><span className="text-[11px] font-bold text-[#7b8780]">سؤال {index + 1} · مستوى {difficultyLabel(question.difficulty)}</span></div><p className="mt-3 text-sm font-black leading-7">{question.prompt}</p><p className="mt-3 rounded-xl bg-[#fbf6eb] px-3 py-2 text-xs leading-6 text-[#79623d]">الدليل: «{question.evidenceQuote}»</p></article>)}</div> : <p className="p-5 text-sm text-[#77847b]">البنك اتجهز لكن ما لقيناش أسئلة للعرض. جرّبوا إنشاء محرك جديد بمصادر أطول.</p>}</section> : null}</> : <section className="surface-card grid min-h-[440px] place-items-center p-8 text-center"><div><Trophy className="mx-auto size-12 text-[#c59a5c]" /><h2 className="mt-4 text-xl font-black">اختاروا محرك أو اعملوا واحد جديد</h2><p className="mt-2 max-w-md text-sm leading-7 text-[#77847b]">{selectedLabel || "كل محرك بيحتفظ بمصادره؛ وده اللي هيخلي الأسئلة مرتبطة بالمحتوى اللي تختاروه فعلًا."}</p></div></section>}</main></section>
  </div>;
}

const outcomeLabel: Record<EvaluatedMatch["evaluations"][number]["outcome"], string> = { correct: "إجابة صحيحة", partial: "إجابة جزئية", incorrect: "إجابة غير صحيحة", manual_review: "تحتاج مراجعة" };
const outcomeTone: Record<EvaluatedMatch["evaluations"][number]["outcome"], string> = { correct: "bg-[#e6f2e5] text-[#367143]", partial: "bg-[#fff3df] text-[#94682e]", incorrect: "bg-[#fff0ee] text-[#a55e58]", manual_review: "bg-[#eceef9] text-[#53618d]" };

function CompetitionQuestionTimer({ match }: { match: CurrentMatch }) {
  const deadline = match.match.status === "question_active" ? match.question?.deadlineAt : null;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { if (!deadline) return; setNow(Date.now()); const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => window.clearInterval(timer); }, [deadline?.getTime()]);
  if (!deadline) return null;
  const seconds = Math.max(0, Math.ceil((new Date(deadline).getTime() - now) / 1000));
  const urgent = seconds <= 10;
  return <section className="page-wrap pt-5"><div className={`mx-auto flex max-w-3xl flex-wrap items-center justify-between gap-3 rounded-2xl border px-5 py-4 ${urgent ? "border-[#f0d5cf] bg-[#fff8f6]" : "border-[#d7e7d7] bg-[#f7fcf5]"}`}><div><p className="card-kicker">مؤقت خادمي</p><h2 className="text-base font-black">وقت السؤال الحالي</h2><p className="mt-1 text-xs leading-6 text-[#718078]">عند الصفر، الخادم يقفل السؤال ويكمل التقييم؛ الوقت في الشاشة للمتابعة فقط.</p></div><div className={`rounded-2xl px-5 py-3 text-center ${urgent ? "bg-[#fff0ed] text-[#aa554c]" : "bg-white text-[#356343]"}`}><p className="text-2xl font-black tabular-nums">{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, "0")}</p><p className="mt-1 text-[10px] font-black">متبقي</p></div></div></section>;
}

function CompetitionRationaleBox({ match }: { match: CurrentMatch }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState("");
  const [saveState, setSaveState] = useState<"ready" | "saving" | "saved" | "error">("ready");
  const savedRef = useRef("");
  const save = trpc.competition.saveRationale.useMutation({ onSuccess: () => { savedRef.current = draft.trim(); setSaveState("saved"); if (member) void utils.competition.currentMatch.invalidate({ memberSlot: member }); }, onError: () => setSaveState("error") });
  const questionId = match.question?.id;
  useEffect(() => { setDraft(""); savedRef.current = ""; setSaveState("ready"); setOpen(false); }, [match.match.id, questionId]);
  useEffect(() => {
    if (!open || !member || !questionId || draft.trim().length < 2 || draft.trim() === savedRef.current) return;
    setSaveState("saving");
    const timer = window.setTimeout(() => save.mutate({ memberSlot: member, matchId: match.match.id, matchQuestionId: questionId, content: draft.trim() }), 700);
    return () => window.clearTimeout(timer);
  }, [draft, member, questionId, match.match.id, open]);
  if (match.match.status !== "question_active" || !match.question) return null;
  return <section className={`rationale-composer mt-4 ${open ? "is-open" : ""}`} aria-label="صندوق التعليلات للجولة الحالية"><button type="button" onClick={() => setOpen(value => !value)} className="rationale-dash" aria-expanded={open}><span className="grid size-9 place-items-center rounded-xl bg-[#eee8fb] text-[#665197]"><MessageSquareText size={17} /></span><span className="flex-1 text-right"><strong className="block text-sm">صندوق التعليلات · الجولة {match.question.order + 1}</strong><span className="mt-0.5 block text-[11px] text-[#726d82]">اكتب سبب اختيارك أو نقطة حيرتك؛ يتحفظ تلقائياً ولا يظهر للخصم قبل الحسم.</span></span><ChevronLeft className={`transition-transform ${open ? "rotate-90" : ""}`} size={19} /></button>{open ? <div className="rationale-drawer ai-alert-enter"><textarea value={draft} onChange={event => setDraft(event.target.value)} maxLength={2200} rows={4} className="field-input min-h-24 w-full resize-y" placeholder="مثال: اخترت الإجابة دي لأن… أو أنا محتار بين…" /><div className="mt-2 flex items-center justify-between gap-3 text-[11px] font-bold"><span className={saveState === "error" ? "text-[#a75750]" : saveState === "saved" ? "text-[#3c754b]" : "text-[#78847d]"}>{saveState === "saving" ? "بيتحفظ تلقائياً…" : saveState === "saved" ? "اتحفظ تعليلك للجولة دي" : saveState === "error" ? "الحفظ ماكملش؛ عدّل النص وسيُعاد تلقائياً" : "اكتب سطرين على الأقل للحفظ التلقائي"}</span><button type="button" onClick={() => setOpen(false)} className="inline-flex items-center gap-1 rounded-lg border border-[#ddd6ef] bg-white px-3 py-1.5 text-[11px] font-black text-[#5a4a87]"><ChevronLeft size={14} />إغلاق الصندوق</button></div></div> : null}</section>;
}

function CompetitionRationaleArchivePanel() {
  const member = useWorkspaceMember();
  const [open, setOpen] = useState(false);
  const [beforeRound, setBeforeRound] = useState<number | undefined>();
  const [selected, setSelected] = useState<RationaleArchiveItem | null>(null);
  const active = trpc.competition.currentMatch.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 4_000 });
  const latest = trpc.competition.latestMatch.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 12_000 });
  const match = (active.data ?? latest.data) as CurrentMatch | null | undefined;
  const archive = trpc.competition.rationaleArchive.useQuery({ memberSlot: member ?? "saif", matchId: match?.match.id ?? 1, beforeRound, limit: 12 }, { enabled: Boolean(member && match), refetchInterval: open ? 10_000 : false });
  const items = (archive.data?.items ?? []) as RationaleArchiveItem[];
  const addOlder = () => { if (archive.data?.nextBeforeRound !== null && archive.data?.nextBeforeRound !== undefined) setBeforeRound(archive.data.nextBeforeRound); };
  if (!match) return null;
  return <section className="page-wrap mb-5"><div className="rationale-archive-shell"><div><p className="card-kicker">أرشيف المنافسة</p><h2 className="mt-1 text-lg font-black">صندوق التعليلات</h2><p className="mt-1 text-xs leading-6 text-[#6f7881]">كل جولة منتهية ليها صندوق محفوظ مستقل: النتيجة، الخصم، التعليلات، وتصحيح لؤي.</p></div><button type="button" onClick={() => setOpen(true)} className="rationale-archive-open"><Archive size={16} />فتح الصناديق ({items.length})</button></div><Dialog open={open} onOpenChange={value => { setOpen(value); if (!value) setSelected(null); }}><DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto border-[#ddd8ec] bg-[#fffdfd] text-right"><DialogHeader><DialogTitle>صندوق التعليلات</DialogTitle><DialogDescription>افتح أي صندوق محفوظ لتشوف الجولة والخصم والتعليلات وتصحيح لؤي.</DialogDescription></DialogHeader>{selected ? <article className="rationale-round-detail ai-alert-enter"><button type="button" onClick={() => setSelected(null)} className="mb-4 inline-flex items-center gap-1 text-xs font-black text-[#5c4c8c]"><ChevronLeft size={14} className="rotate-180" />كل الصناديق</button><p className="card-kicker">الجولة {selected.round} · ضد {competitorLabel(selected.opponentKey)}</p><h3 className="mt-1 text-lg font-black">{selected.winnerKey ? `${competitorLabel(selected.winnerKey)} كسب الجولة` : "الجولة انتهت بتعادل"}</h3><p className="mt-3 rounded-2xl bg-[#f8faf7] p-4 text-sm font-bold leading-7">{selected.questionPrompt}</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{selected.rationales.length ? selected.rationales.map(item => <div key={item.authorKey} className="rounded-2xl border border-[#e5e1ef] bg-white p-4"><p className="text-xs font-black text-[#5d4d8e]">تعليل {competitorLabel(item.authorKey)}</p><p className="mt-2 text-sm leading-7 text-[#5e6770]">{item.content}</p></div>) : <p className="rounded-2xl bg-[#faf9f6] p-4 text-sm text-[#75817b]">لم يُكتب تعليل في هذه الجولة.</p>}</div>{selected.rashed ? <div className="mt-3 rounded-2xl border border-[#e0d8f0] bg-[#fbf9ff] p-4"><p className="text-xs font-black text-[#5f4d91]">رد راشد وتعليله</p><p className="mt-2 text-sm leading-7">الإجابة: {selected.rashed.answerText}</p>{selected.rashed.rationale ? <p className="mt-1 text-xs leading-6 text-[#6d687e]">تعليله: {selected.rashed.rationale}</p> : null}<p className="mt-2 text-xs leading-6 text-[#6d687e]">حكم لؤي: {selected.rashed.judgeReason || "قيد التقييم"}</p></div> : null}{selected.loayReview ? <div className="mt-3 rounded-2xl border border-[#d8e7d7] bg-[#f5fbf4] p-4"><p className="text-xs font-black text-[#3d6d49]">تصحيح لؤي وخطوة الإصلاح</p><p className="mt-2 whitespace-pre-wrap text-sm leading-7 text-[#526459]">{selected.loayReview}</p></div> : null}</article> : <div className="mt-4 grid gap-3 sm:grid-cols-2">{items.map(item => <button type="button" key={item.round} onClick={() => setSelected(item)} className="rationale-archive-dash text-right"><MessageSquareText size={18} /><span><strong className="block">صندوق الجولة {item.round}</strong><small>ضد {competitorLabel(item.opponentKey)} · {item.winnerKey ? `${competitorLabel(item.winnerKey)} فاز` : "تعادل"}</small></span><ChevronLeft size={16} /></button>)}{!items.length ? <p className="rounded-2xl bg-[#faf9f6] p-5 text-sm text-[#75817b]">أول صندوق هيتحفظ بعد ما تخلصوا أول جولة.</p> : null}</div>}{archive.data?.nextBeforeRound !== null && archive.data?.nextBeforeRound !== undefined && !selected ? <button type="button" onClick={addOlder} className="mt-4 rounded-xl border border-[#dcd7ec] bg-white px-4 py-2 text-xs font-black text-[#5c4c8c]">عرض صناديق أقدم</button> : null}</DialogContent></Dialog></section>;
}

function CompetitionLeaveControl({ match }: { match: CurrentMatch | EvaluatedMatch }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const beforeStart = ["waiting", "ready"].includes(match.match.status);
  const leave = trpc.competition.leaveMatch.useMutation({
    onSuccess: result => {
      setOpen(false);
      if (member) void Promise.all([
        utils.competition.currentMatch.invalidate({ memberSlot: member }),
        utils.competition.latestMatch.invalidate({ memberSlot: member }),
        utils.competition.history.invalidate(),
      ]);
      toast.success(result.kind === "forfeit" ? "اتسجل خروجك، واتحسمت النتيجة للطرف الآخر." : "تم إلغاء الدعوة قبل بدء المنافسة، ولم تُحسب جلسة.");
    },
    onError: error => toast.error(error.message),
  });
  if (!member || ["finished", "cancelled"].includes(match.match.status)) return null;
  return <><div className="page-wrap pt-3"><div className="mx-auto flex max-w-3xl justify-end"><button type="button" onClick={() => setOpen(true)} className="inline-flex items-center gap-2 rounded-xl border border-[#ead8d3] bg-white px-3 py-2 text-xs font-black text-[#9a4d41]"><LogOut size={15} />{beforeStart ? "إلغاء الدعوة" : "الخروج من المنافسة"}</button></div></div><AlertDialog open={open} onOpenChange={setOpen}><AlertDialogContent dir="rtl" className="border-[#ead8d3] text-right"><AlertDialogHeader><AlertDialogTitle>{beforeStart ? "إلغاء الدعوة قبل البدء؟" : "الخروج من المنافسة؟"}</AlertDialogTitle><AlertDialogDescription>{beforeStart ? "لن تُحسب دعوة لم تبدأ كمنافسة، ولن تتغير أي نتيجة." : "سيُسجل خروجك من المباراة التي بدأت، ويُحسم الفوز للطرف الآخر مع بقاء النقاط والتعليلات المحفوظة."}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter className="flex-row-reverse gap-2 sm:justify-start"><AlertDialogCancel disabled={leave.isPending}>رجوع</AlertDialogCancel><AlertDialogAction disabled={leave.isPending} onClick={event => { event.preventDefault(); leave.mutate({ memberSlot: member, matchId: match.match.id }); }} className="bg-[#9a4d41] text-white hover:bg-[#813d34]">{leave.isPending ? "جارٍ الخروج…" : "تأكيد الخروج"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function CompetitionForfeitNotice({ match }: { match: EvaluatedMatch }) {
  if (match.result?.completionReason !== "forfeit" || !match.result.forfeitedBy) return null;
  const winner = match.result.winnerKey ? competitorLabel(match.result.winnerKey) : "الطرف الآخر";
  return <section className="page-wrap pt-4"><div className="mx-auto max-w-3xl rounded-2xl border border-[#f0d7d0] bg-[#fff7f4] px-5 py-4"><p className="card-kicker text-[#9a4d41]">انتهت المنافسة بخروج لاعب</p><p className="mt-1 text-sm font-black text-[#743b33]">{memberLabel(match.result.forfeitedBy)} خرج من المنافسة؛ فاز {winner} وحُفظت النتيجة والنقاط الحالية.</p></div></section>;
}

function CompetitionSessionRationalePreview({ matchId }: { matchId: number }) {
  const member = useWorkspaceMember();
  const archive = trpc.competition.rationaleArchive.useQuery({ memberSlot: member ?? "saif", matchId, limit: 3 }, { enabled: Boolean(member) });
  const items = (archive.data?.items ?? []) as RationaleArchiveItem[];
  return <div className="mt-3 rounded-2xl border border-[#e2e8df] bg-[#fbfdf9] p-3"><p className="text-xs font-black text-[#496756]">صندوق التعليلات وتصحيح لؤي</p>{archive.isLoading ? <p className="mt-2 text-xs text-[#77847b]">جارٍ تحميل الصناديق المحفوظة…</p> : items.length ? <div className="mt-2 space-y-2">{items.map(item => <div key={item.round} className="rounded-xl bg-white px-3 py-2 text-xs leading-6 text-[#5c6961]"><strong>الجولة {item.round}:</strong> {item.winnerKey ? `${competitorLabel(item.winnerKey)} كسبها.` : "تعادل."}{item.loayReview ? <span className="block mt-1 text-[#4d6654]">{item.loayReview.slice(0, 220)}{item.loayReview.length > 220 ? "…" : ""}</span> : <span className="block mt-1 text-[#7b847e]">لا يوجد تصحيح لؤي محفوظ لهذه الجولة.</span>}</div>)}</div> : <p className="mt-2 text-xs leading-6 text-[#77847b]">لا يوجد صندوق جولة؛ الخروج حدث قبل حسم سؤال، أو لم يُكتب تعليل بعد.</p>}</div>;
}

function CompetitionRashedRoundResult({ match }: { match: EvaluatedMatch }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const advance = trpc.competition.advanceMatch.useMutation({ onSuccess: () => { if (member) void utils.competition.currentMatch.invalidate({ memberSlot: member }); toast.success("اتنقلنا للجولة التالية مع راشد."); }, onError: error => toast.error(error.message) });
  if (match.match.mode !== "rashed" || !match.rashed || match.match.status !== "showing_result") return null;
  const mine = match.players.find(player => player.memberSlot === member)?.memberSlot;
  const myEvaluation = match.evaluations.find(item => item.memberSlot === mine);
  const winner = (myEvaluation?.awardedPoints ?? 0) === (match.rashed.awardedPoints ?? 0) ? "الجولة تعادلت" : (myEvaluation?.awardedPoints ?? 0) > (match.rashed.awardedPoints ?? 0) ? `${member ? memberLabel(member) : "أنت"} كسب الجولة` : "راشد كسب الجولة";
  return <section className="page-wrap pt-5"><CompetitionRashedPresence match={match} compact /><div className="mx-auto max-w-3xl overflow-hidden rounded-[1.6rem] border border-[#ded7ee] bg-[#fbfaff] shadow-[0_18px_42px_rgba(83,65,132,.09)]"><div className="border-b border-[#e7e1f2] px-5 py-4"><p className="card-kicker">لؤي · نتيجة مواجهة راشد</p><h2 className="mt-1 text-lg font-black">{winner}</h2><p className="mt-1 text-xs leading-6 text-[#6f687d]">راشد كان رده مخفي لحد الحسم؛ دلوقتي تقدر تشوف تعليله وحكم لؤي عليه.</p></div><div className="grid gap-3 p-5 sm:grid-cols-2"><article className="rounded-2xl bg-white p-4"><p className="text-xs font-black text-[#497054]">نتيجتك</p><p className="mt-2 text-sm leading-7">{myEvaluation?.reason || "قيد التقييم"}</p><p className="mt-2 text-xs font-bold text-[#708077]">نقاط الجولة: {myEvaluation?.awardedPoints ?? 0}</p></article><article className="rounded-2xl border border-[#e2dcf0] bg-white p-4"><p className="text-xs font-black text-[#5d4b8b]">راشد</p><p className="mt-2 text-sm leading-7">إجابته: {match.rashed.answerText || "غير متاحة"}</p>{match.rashed.rationale ? <p className="mt-1 text-xs leading-6 text-[#6c657b]">تعليله: {match.rashed.rationale}</p> : null}<p className="mt-2 text-xs leading-6 text-[#6c657b]">حكم لؤي: {match.rashed.judgeReason || "قيد التقييم"}</p><p className="mt-2 text-xs font-bold text-[#6c657b]">نقاطه: {match.rashed.awardedPoints ?? 0} · الإجمالي: {match.rashed.score}</p></article></div>{match.rationales.length ? <div className="mx-5 mb-4 rounded-2xl bg-white p-4"><p className="text-xs font-black text-[#5b4b87]">تعليلات الجولة</p>{match.rationales.map(item => <p key={item.authorKey} className="mt-2 text-sm leading-7 text-[#5e6670}"><strong>{competitorLabel(item.authorKey)}:</strong> {item.content}</p>)}</div> : null}{match.loayReview ? <div className="mx-5 mb-4 rounded-2xl border border-[#d8e7d7] bg-[#f5fbf4] p-4"><p className="text-xs font-black text-[#3f704c]">تصحيح لؤي وخطوة الإصلاح</p><p className="mt-2 whitespace-pre-wrap text-sm leading-7 text-[#52635a]">{match.loayReview.reviewText}</p></div> : null}<div className="border-t border-[#e7e1f2] p-5"><button type="button" disabled={!member || advance.isPending} onClick={() => advance.mutate({ memberSlot: member!, matchId: match.match.id })} className="inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-[#62508f] px-4 py-3 text-sm font-black text-white disabled:opacity-50">{advance.isPending ? "لؤي يجهز الخطوة التالية…" : match.match.currentQuestionOrder + 1 < match.match.questionTotal ? "السؤال التالي ضد راشد" : "إنهاء مواجهة راشد"}</button></div></div></section>;
}

function CompetitionRashedFinalResult({ match, onDismiss }: { match: EvaluatedMatch; onDismiss: () => void }) {
  if (match.match.mode !== "rashed" || match.match.status !== "finished") return null;
  const winnerKey = match.result?.winnerKey ?? null;
  const winnerText = winnerKey === "rashed" ? "راشد كسب المواجهة" : winnerKey ? `${competitorLabel(winnerKey)} كسب المواجهة` : "المواجهة انتهت بتعادل";
  const human = match.players[0]?.memberSlot;
  const humanPoints = human === "saif" ? match.result?.saifPoints ?? match.scores.saif : match.result?.haneenPoints ?? match.scores.haneen;
  return <section className="page-wrap pt-6"><CompetitionRashedPresence match={match} compact /><div className="mx-auto max-w-3xl overflow-hidden rounded-[1.7rem] border border-[#ded7ee] bg-[#fbfaff] shadow-[0_18px_42px_rgba(83,65,132,.09)]"><div className="p-6 text-center sm:p-8"><Bot className="mx-auto size-11 text-[#665196]" /><p className="card-kicker mt-3">النتيجة النهائية · مواجهة راشد</p><h1 className="mt-1 text-2xl font-black">{winnerText}</h1><p className="mt-2 text-sm leading-7 text-[#6c667a]">هذه نتيجة مواجهة فردية تعليمية؛ لا تُضاف إلى سجل انتصارات سيف وحنين في المنافسة الثنائية.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-white p-4"><p className="text-xs font-black text-[#3e704d]">{human ? memberLabel(human) : "أنت"}</p><p className="mt-1 text-3xl font-black text-[#315e40]">{humanPoints}</p><p className="text-xs text-[#728079]">نقطة</p></div><div className="rounded-2xl border border-[#e2dcf0] bg-white p-4"><p className="text-xs font-black text-[#5d4b8b]">راشد</p><p className="mt-1 text-3xl font-black text-[#5d4b8b]">{match.result?.rashedPoints ?? match.rashed?.score ?? 0}</p><p className="text-xs text-[#728079]">نقطة</p></div></div><button type="button" onClick={onDismiss} className="mt-5 w-full rounded-2xl border border-[#d8d2e7] bg-white px-4 py-3 text-sm font-black text-[#5d4b8b]">الرجوع للمحركات وصندوق التعليلات</button></div></div></section>;
}

function CompetitionManualReviewPanel({ match }: { match: EvaluatedMatch }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const [selectedOutcomes, setSelectedOutcomes] = useState<Record<number, "correct" | "partial" | "incorrect">>({});
  const [notes, setNotes] = useState<Record<number, string>>({});
  const refresh = async () => { if (member) await Promise.all([utils.competition.currentMatch.invalidate({ memberSlot: member }), utils.competition.getMatch.invalidate({ memberSlot: member, matchId: match.match.id })]); };
  const propose = trpc.competition.proposeManualReview.useMutation({ onSuccess: () => { void refresh(); toast.success("اتسجل اقتراحك للمراجعة، ومستنيين تأكيد الطرف التاني."); }, onError: error => toast.error(error.message) });
  const confirm = trpc.competition.confirmManualReview.useMutation({ onSuccess: () => { void refresh(); toast.success("اتأكدت المراجعة واتحسبت النتيجة من الخادم."); }, onError: error => toast.error(error.message) });
  const pending = match.evaluations.filter(item => item.outcome === "manual_review");
  if (!pending.length) return null;
  return <section className="page-wrap pt-6"><div className="mx-auto max-w-3xl rounded-[1.6rem] border border-[#e6dcb9] bg-[#fffaf0] p-5 shadow-[0_16px_38px_rgba(151,104,38,.08)] sm:p-6"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#fff0cf] text-[#9a6c2a]"><Star size={19} fill="currentColor" /></div><div><p className="card-kicker">حسم مشترك</p><h2 className="text-lg font-black">لؤي محتاج تأكيد منكم</h2><p className="mt-1 text-xs leading-6 text-[#7c704f]">صاحب الإجابة يقترح الحكم؛ واللاعب التاني وحده يقدر يؤكده. مفيش نقاط بتتغير قبل التأكيد.</p></div></div><div className="mt-4 space-y-3">{pending.map(item => <article key={item.id} className="rounded-2xl border border-[#eee3c9] bg-white p-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-black">مراجعة إجابة {memberLabel(item.memberSlot)}</p><span className="rounded-full bg-[#eceef9] px-2.5 py-1 text-[11px] font-black text-[#53618d]">تحتاج مراجعة</span></div>{!item.reviewProposedBy && item.memberSlot === member ? <div className="mt-3 grid gap-2 sm:grid-cols-[.7fr_1fr_auto]"><select value={selectedOutcomes[item.id] || "partial"} onChange={event => setSelectedOutcomes(current => ({ ...current, [item.id]: event.target.value as "correct" | "partial" | "incorrect" }))} className="field-input text-xs" disabled={propose.isPending}><option value="correct">إجابة صحيحة</option><option value="partial">إجابة جزئية</option><option value="incorrect">إجابة غير صحيحة</option></select><input value={notes[item.id] || ""} onChange={event => setNotes(current => ({ ...current, [item.id]: event.target.value }))} maxLength={1200} className="field-input text-xs" placeholder="سبب مختصر اختياري" disabled={propose.isPending} /><button type="button" disabled={propose.isPending} onClick={() => propose.mutate({ memberSlot: member, matchId: match.match.id, evaluationId: item.id, outcome: selectedOutcomes[item.id] || "partial", note: notes[item.id] || undefined })} className="rounded-xl bg-[#87642f] px-4 py-2 text-xs font-black text-white disabled:opacity-50">اقتراح الحكم</button></div> : item.reviewProposedBy && item.memberSlot !== member ? <div className="mt-3 flex flex-wrap items-center gap-2"><p className="text-xs leading-6 text-[#786d51]">{memberLabel(item.reviewProposedBy)} اقترح: <strong>{outcomeLabel[item.reviewProposedOutcome || "manual_review"]}</strong>{item.reviewNote ? ` — ${item.reviewNote}` : ""}</p><button type="button" disabled={confirm.isPending || !member} onClick={() => confirm.mutate({ memberSlot: member!, matchId: match.match.id, evaluationId: item.id })} className="rounded-xl bg-[#2d5b4b] px-4 py-2 text-xs font-black text-white disabled:opacity-50">تأكيد المراجعة</button></div> : <p className="mt-3 text-xs leading-6 text-[#786d51]">{item.reviewProposedBy ? `اقتراح ${memberLabel(item.reviewProposedBy)} مسجل؛ مستنيين تأكيد اللاعب التاني.` : "صاحب الإجابة هو اللي يقدر يبدأ الاقتراح."}</p>}</article>)}</div></div></section>;
}

function CompetitionEvaluationStage({ match, onDismiss }: { match: EvaluatedMatch; onDismiss?: () => void }) {
  const member = useWorkspaceMember();
  const utils = trpc.useUtils();
  const advance = trpc.competition.advanceMatch.useMutation({ onSuccess: () => { if (member) void utils.competition.currentMatch.invalidate({ memberSlot: member }); toast.success("اتنقلنا للمرحلة التالية."); }, onError: error => toast.error(error.message) });
  if (match.match.mode === "rashed") return null;
  const winnerText = match.result?.winnerSlot ? `${memberLabel(match.result.winnerSlot)} كسب المباراة` : "المباراة انتهت بتعادل";
  return <div className="page-wrap"><header className="mb-7"><p className="eyebrow">لؤي · نتيجة الجولة</p><h1 className="page-title">{match.match.status === "finished" ? winnerText : "نتيجة السؤال"}</h1><p className="mt-2 text-sm leading-7 text-[#748078]">النقاط والحكم جاية من الخادم. لؤي لا يغيّر النتيجة وحده ولا يستقبل نقاطاً من المتصفح.</p></header><section className="mx-auto max-w-3xl overflow-hidden rounded-[1.75rem] border border-[#dbe8d8] bg-[#fbfdf9] shadow-[0_20px_48px_rgba(43,94,72,.08)]"><div className="grid gap-3 border-b border-[#e4eee1] bg-[#f2f8f0] p-5 sm:grid-cols-2 sm:p-7"><div className="rounded-2xl bg-white p-4"><p className="text-xs font-bold text-[#728079]">سيف</p><p className="mt-1 text-3xl font-black text-[#315e40]">{match.scores.saif}</p><p className="text-xs text-[#728079]">نقطة</p></div><div className="rounded-2xl bg-white p-4"><p className="text-xs font-bold text-[#728079]">حنين</p><p className="mt-1 text-3xl font-black text-[#315e40]">{match.scores.haneen}</p><p className="text-xs text-[#728079]">نقطة</p></div></div>{match.match.status === "showing_result" ? <div className="p-5 sm:p-7"><div className="mb-5 rounded-2xl bg-white p-4"><p className="text-sm font-black leading-7">{match.question?.prompt || "السؤال الذي تم تقييمه"}</p><p className="mt-2 text-xs leading-6 text-[#77847b]">الإجابات نفسها مخفية؛ الظاهر هنا هو الحكم وسببه فقط بعد اكتمال الإرسال للطرفين.</p></div><div className="space-y-3">{match.evaluations.map(evaluation => <article key={evaluation.memberSlot} className="rounded-2xl border border-[#e6ece3] bg-white p-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-black">{memberLabel(evaluation.memberSlot)}</p><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ${outcomeTone[evaluation.outcome]}`}>{outcomeLabel[evaluation.outcome]}</span></div><p className="mt-3 text-sm leading-7 text-[#5f6d64]">{evaluation.reason}</p><p className="mt-2 text-xs font-bold text-[#78847d]">ثقة التقييم: {evaluation.confidence}% · نقاط الجولة: {evaluation.awardedPoints}</p></article>)}</div><button type="button" disabled={!member || advance.isPending || match.evaluations.length !== 2} onClick={() => advance.mutate({ memberSlot: member!, matchId: match.match.id })} className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-[#2d5b4b] px-4 py-3 text-sm font-black text-white disabled:opacity-50">{advance.isPending ? "جارٍ التأكيد…" : match.match.currentQuestionOrder + 1 < match.match.questionTotal ? "السؤال التالي" : "إنهاء المباراة وإعلان النتيجة"}</button></div> : <div className="p-6 sm:p-8"><div className="rounded-2xl bg-white p-5 text-center"><Trophy className="mx-auto size-11 text-[#bd8d4a]" /><h2 className="mt-3 text-xl font-black">{winnerText}</h2><p className="mt-2 text-sm leading-7 text-[#65736b]">سيف: {match.result?.saifPoints ?? match.scores.saif} نقطة · حنين: {match.result?.haneenPoints ?? match.scores.haneen} نقطة</p></div><p className="mt-5 text-center text-xs leading-6 text-[#748078]">ستضاف مراجعة الأخطاء والإحصاءات وسجل الانتصارات في المرحلة التالية؛ لا توجد أرقام تجريبية هنا.</p>{onDismiss ? <button type="button" onClick={onDismiss} className="mt-5 w-full rounded-2xl border border-[#d8e4d6] bg-white px-4 py-3 text-sm font-black text-[#416d50]">الرجوع للمحركات</button> : null}</div>}</section></div>;
}

function CompetitionAchievementCelebration({ match, compact = false }: { match: EvaluatedMatch; compact?: boolean }) {
  const winnerText = match.result?.winnerKey ? `الفائز: ${competitorLabel(match.result.winnerKey)}` : "النتيجة: تعادل";
  return <section className={`competition-achievement-celebration ${compact ? "is-compact" : ""}`} role="status" aria-live="polite"><div className="competition-confetti" aria-hidden="true">{Array.from({ length: 14 }, (_, index) => <i key={index} className={`competition-confetti-paper paper-${index + 1}`} />)}</div><div className="competition-achievement-medal" aria-hidden="true"><Trophy size={24} /><Sparkles className="competition-achievement-sparkle" size={16} /></div><div className="min-w-0"><p className="card-kicker">إنجاز جديد اتسجل</p><h2>جلسة المنافسة اتحفظت بنجاح</h2><p>{winnerText} · النتيجة والنقاط وصندوق التعليلات محفوظين في السجل.</p></div><span className="competition-achievement-check" aria-label="تم تسجيل الجلسة">✓</span></section>;
}

function CompetitionProgressChart({ items, member }: { items: CompetitionHistory["sessionItems"]; member: Member }) {
  const [rangeMode, setRangeMode] = useState<"current_year" | "custom">("current_year");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [metric, setMetric] = useState<"scores" | "timeouts">("scores");
  const [activePointIndex, setActivePointIndex] = useState<number | null>(null);
  const allPoints = [...items].sort((left, right) => new Date(left.finishedAt).getTime() - new Date(right.finishedAt).getTime());
  const currentYear = new Date().getFullYear();
  const customStart = startDate ? new Date(`${startDate}T00:00:00`) : null;
  const customEnd = endDate ? new Date(`${endDate}T23:59:59.999`) : null;
  const rangeError = rangeMode === "custom" && ((!customStart && !customEnd) || (customStart && Number.isNaN(customStart.getTime())) || (customEnd && Number.isNaN(customEnd.getTime())) || Boolean(customStart && customEnd && customStart > customEnd));
  const points = allPoints.filter(item => {
    const finishedAt = new Date(item.finishedAt);
    if (rangeMode === "current_year") return finishedAt.getFullYear() === currentYear;
    if (rangeError || Number.isNaN(finishedAt.getTime())) return false;
    return (!customStart || finishedAt >= customStart) && (!customEnd || finishedAt <= customEnd);
  }).slice(-8);
  const filterControls = <div className="competition-chart-filters" role="group" aria-label="تصفية وخيارات الرسم البياني"><span className="competition-chart-filter-label">عرض الفترة</span><button type="button" className={rangeMode === "current_year" ? "is-active" : ""} aria-pressed={rangeMode === "current_year"} onClick={() => setRangeMode("current_year")}>العام الحالي ({currentYear})</button><button type="button" className={rangeMode === "custom" ? "is-active" : ""} aria-pressed={rangeMode === "custom"} onClick={() => setRangeMode("custom")}>نطاق مخصص</button>{rangeMode === "custom" ? <><label>من <input type="date" value={startDate} onChange={event => setStartDate(event.target.value)} /></label><label>إلى <input type="date" value={endDate} onChange={event => setEndDate(event.target.value)} /></label></> : null}<label className="competition-chart-metric">المؤشر <select value={metric} onChange={event => { setMetric(event.target.value as "scores" | "timeouts"); setActivePointIndex(null); }} aria-label="مؤشر الرسم"><option value="scores">النقاط مقابل الخصم</option><option value="timeouts">الجلسات التي تجاوزت المهلة</option></select></label></div>;
  const exportRows = points.map((item, index) => ({ "رقم الجلسة": index + 1, "التاريخ": new Date(item.finishedAt).toLocaleString("ar-EG"), "المحرك": item.engineTitle, "النمط": item.mode === "rashed" ? "مواجهة راشد" : "مواجهة ثنائية", "الحالة": item.completionReason === "forfeit" ? "انتهت بخروج لاعب" : "مكتملة", "جلسات المهلة داخل الجولة": item.timedOutQuestionCount, "نقاطي": member === "saif" ? item.saifPoints : item.haneenPoints, "نقاط الخصم": item.mode === "rashed" ? item.rashedPoints : member === "saif" ? item.haneenPoints : item.saifPoints, "الفائز": item.winnerKey ? competitorLabel(item.winnerKey) : "تعادل" }));
  const downloadCsv = () => { const headers = Object.keys(exportRows[0] ?? { "رقم الجلسة": "" }); const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`; const csv = `\uFEFF${[headers, ...exportRows.map(row => headers.map(header => row[header as keyof typeof row]))].map(row => row.map(escape).join(",")).join("\r\n")}`; const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `saf-haneen-competition-${rangeMode}.csv`; anchor.click(); URL.revokeObjectURL(url); toast.success("اتجهز ملف CSV بالجلسات الظاهرة."); };
  const downloadExcel = () => { const sheet = XLSX.utils.json_to_sheet(exportRows); const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, "جلسات المنافسة"); XLSX.writeFile(workbook, `saf-haneen-competition-${rangeMode}.xlsx`); toast.success("اتجهز ملف Excel بالجلسات الظاهرة."); };
  if (rangeError || !points.length) return <section className="competition-progress-chart" aria-label="رسم بياني لتطور نقاط جلسات المنافسة">{filterControls}<div className="competition-chart-empty">{rangeError ? "اختاروا تاريخ بداية ونهاية صالحين؛ البداية لازم تكون قبل النهاية." : rangeMode === "current_year" ? `مفيش جلسات محفوظة في ${currentYear} لسه.` : "مفيش جلسات محفوظة داخل النطاق ده."}</div></section>;
  const chartWidth = 640;
  const chartHeight = 190;
  const chartPadding = { top: 18, right: 18, bottom: 34, left: 34 };
  const mineScores = points.map(item => member === "saif" ? item.saifPoints : item.haneenPoints);
  const opponentScores = points.map(item => item.mode === "rashed" ? item.rashedPoints : member === "saif" ? item.haneenPoints : item.saifPoints);
  const timeoutScores = points.map(item => item.timedOutQuestionCount);
  const values = metric === "scores" ? [...mineScores, ...opponentScores] : timeoutScores;
  const maxValue = Math.max(1, ...values);
  const toX = (index: number) => chartPadding.left + (index / Math.max(1, points.length - 1)) * (chartWidth - chartPadding.left - chartPadding.right);
  const toY = (value: number) => chartPadding.top + (1 - value / maxValue) * (chartHeight - chartPadding.top - chartPadding.bottom);
  const mine = mineScores.map((score, index) => ({ x: toX(index), y: toY(score), score }));
  const opponent = opponentScores.map((score, index) => ({ x: toX(index), y: toY(score), score }));
  const timeouts = timeoutScores.map((score, index) => ({ x: toX(index), y: toY(score), score }));
  const line = (valuesToDraw: Array<{ x: number; y: number }>) => valuesToDraw.map((point, index) => `${index ? "L" : "M"} ${point.x.toFixed(1)} ${point.y.toFixed(1)}`).join(" ");
  const activeItem = activePointIndex === null ? null : points[activePointIndex] ?? null;
  const activeMineScore = activeItem ? member === "saif" ? activeItem.saifPoints : activeItem.haneenPoints : 0;
  const activeOpponentScore = activeItem ? activeItem.mode === "rashed" ? activeItem.rashedPoints : member === "saif" ? activeItem.haneenPoints : activeItem.saifPoints : 0;
  const activeOpponent = activeItem ? activeItem.mode === "rashed" ? "راشد" : member === "saif" ? "حنين" : "سيف" : "الخصم";
  const activeResult = activeItem ? activeItem.winnerKey ? `الفائز: ${competitorLabel(activeItem.winnerKey)}` : "النتيجة: تعادل" : "";
  const activeFinishedAt = activeItem ? new Date(activeItem.finishedAt).toLocaleString("ar-EG", { dateStyle: "medium", timeStyle: "short" }) : "";
  const activatePoint = (index: number) => setActivePointIndex(index);
  const pointProps = (index: number) => ({ tabIndex: 0, role: "button" as const, "aria-label": `تفاصيل جلسة ${index + 1}`, onMouseEnter: () => activatePoint(index), onFocus: () => activatePoint(index), onBlur: () => setActivePointIndex(null) });
  return <section className="competition-progress-chart" aria-label="رسم بياني لتطور جلسات المنافسة">{filterControls}<div className="competition-chart-heading"><div><p className="card-kicker">منحنى التقدم</p><h3 className="mt-1 text-base font-black">{metric === "scores" ? `تطور آخر ${points.length} جلسات` : `جلسات تجاوزت المهلة · ${timeoutScores.reduce((sum, value) => sum + value, 0)} سؤال`}</h3><p className="mt-1 text-xs leading-6 text-[#748078]">{metric === "scores" ? "النقاط المعروضة مأخوذة من النتائج المحفوظة فعلاً، والأحدث جهة اليمين." : "العدد مستخرج من الإجابات التي سجّلها الخادم تلقائياً عند انتهاء مهلة السؤال."}</p></div>{metric === "scores" ? <div className="competition-chart-legend"><span><i className="is-mine" />{memberLabel(member)}</span><span><i className="is-opponent" />الخصم</span></div> : <span className="competition-chart-timeout-total">{points.filter(item => item.timedOutQuestionCount > 0).length} جلسة</span>}</div><div className="competition-chart-actions"><button type="button" onClick={downloadCsv} title="تنزيل البيانات الظاهرة بصيغة CSV"><Download size={15} />CSV</button><button type="button" onClick={downloadExcel} title="تنزيل البيانات الظاهرة بصيغة Excel"><FileSpreadsheet size={15} />Excel</button></div><div className="competition-chart-frame"><svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} role="img" aria-label={metric === "scores" ? `تطور نقاط ${memberLabel(member)} في آخر ${points.length} جلسات` : "عدد جلسات تجاوزت المهلة"} preserveAspectRatio="none"><line className="competition-chart-axis" x1={chartPadding.left} x2={chartWidth - chartPadding.right} y1={chartHeight - chartPadding.bottom} y2={chartHeight - chartPadding.bottom} /><line className="competition-chart-axis" x1={chartPadding.left} x2={chartPadding.left} y1={chartPadding.top} y2={chartHeight - chartPadding.bottom} /><line className="competition-chart-grid" x1={chartPadding.left} x2={chartWidth - chartPadding.right} y1={toY(maxValue / 2)} y2={toY(maxValue / 2)} />{metric === "scores" ? <><path className="competition-chart-line is-opponent" d={line(opponent)} /><path className="competition-chart-line is-mine" d={line(mine)} />{mine.map((point, index) => <g key={`${points[index]!.matchId}-mine`}><circle className="competition-chart-dot is-mine" cx={point.x} cy={point.y} r="4" {...pointProps(index)} /><title>{`${index + 1}: ${point.score} نقطة لـ${memberLabel(member)}`}</title></g>)}{opponent.map((point, index) => <g key={`${points[index]!.matchId}-opponent`}><circle className="competition-chart-dot is-opponent" cx={point.x} cy={point.y} r="3.5" {...pointProps(index)} /><title>{`${index + 1}: ${point.score} نقطة للخصم`}</title></g>)}</> : <><path className="competition-chart-line is-timeout" d={line(timeouts)} />{timeouts.map((point, index) => <g key={`${points[index]!.matchId}-timeout`}><circle className="competition-chart-dot is-timeout" cx={point.x} cy={point.y} r="4" {...pointProps(index)} /><title>{`${index + 1}: ${point.score} سؤال انتهت مهلته`}</title></g>)}</>}</svg></div><div className="competition-chart-tooltip-slot" aria-live="polite">{activeItem ? <div className="competition-chart-tooltip"><strong>الجلسة {activePointIndex! + 1} · {activeResult}</strong><span>{activeFinishedAt} · {activeItem.engineTitle}</span>{metric === "scores" ? <span>{memberLabel(member)}: {activeMineScore} نقطة · {activeOpponent}: {activeOpponentScore} نقطة</span> : <span>{activeItem.timedOutQuestionCount} سؤال انتهت مهلته داخل هذه الجلسة</span>}<small>{activeItem.completionReason === "forfeit" ? "انتهت بخروج لاعب" : activeItem.mode === "rashed" ? "مواجهة راشد" : "مواجهة ثنائية"}</small></div> : <span className="competition-chart-tooltip-hint">مرّر المؤشر أو استخدم التركيز على أي نقطة لعرض تفاصيل الجلسة.</span>}</div><div className="competition-chart-labels" aria-hidden="true">{points.map((item, index) => <span key={item.matchId}>{index + 1}</span>)}</div></section>;
}

function CompetitionHistorySkeleton() {
  return <section className="page-wrap mb-5" aria-label="جاري تحميل إنجازات المنافسة" aria-busy="true"><div className="competition-history-skeleton"><div className="competition-skeleton-bar is-short" /><div className="competition-skeleton-bar is-title" /><div className="competition-skeleton-chart"><span /><span /><span /><span /><span /></div><div className="competition-skeleton-cards"><span /><span /><span /></div></div></section>;
}

function CompetitionPerformanceSparkline({ values, label, color }: { values: number[]; label: string; color: string }) {
  if (!values.length) return <div className="competition-sparkline-empty" role="img" aria-label={`${label}: لا توجد جلسات محفوظة حتى الآن`}>لا توجد جلسات كافية</div>;
  const width = 160;
  const height = 42;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const spread = Math.max(1, max - min);
  const points = values.map((value, index) => `${values.length === 1 ? width / 2 : (index / (values.length - 1)) * width},${height - 6 - ((value - min) / spread) * (height - 12)}`).join(" ");
  return <svg className="competition-performance-sparkline" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${label}: اتجاه النقاط عبر ${values.length} جلسات`} tabIndex={0} focusable="true"><polyline fill="none" points={points} stroke={color} strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" />{values.map((value, index) => { const [x, y] = points.split(" ")[index]!.split(","); return <circle key={`${label}-${index}`} cx={x} cy={y} fill="#fff" r="3" stroke={color} strokeWidth="2"><title>الجلسة {index + 1}: {value} نقطة</title></circle>; })}</svg>;
}

function competitionTrend(values: number[]) {
  if (values.length < 2) return { kind: "neutral" as const, label: "بيانات أولية", description: "نحتاج جلسة أخرى لتحديد الاتجاه" };
  const recent = values.slice(-3).reduce((sum, value) => sum + value, 0) / Math.min(3, values.length);
  const previousValues = values.slice(Math.max(0, values.length - 6), Math.max(0, values.length - 3));
  const previous = previousValues.length ? previousValues.reduce((sum, value) => sum + value, 0) / previousValues.length : values[0]!;
  if (recent > previous) return { kind: "up" as const, label: "في تحسن", description: "متوسط النقاط الأخير أعلى" };
  if (recent < previous) return { kind: "down" as const, label: "يحتاج دفعة", description: "متوسط النقاط الأخير أقل" };
  return { kind: "neutral" as const, label: "مستقر", description: "متوسط النقاط ثابت تقريباً" };
}

function CompetitionTrendBadge({ values }: { values: number[] }) {
  const trend = competitionTrend(values);
  const Icon = trend.kind === "up" ? TrendingUp : trend.kind === "down" ? TrendingDown : Minus;
  return <span className={`competition-trend-badge is-${trend.kind}`} title={trend.description}><Icon size={14} aria-hidden="true" />{trend.label}</span>;
}

function CompetitionPerformanceCard({ member, values }: { member: Member; values: number[] }) {
  return <article className={`competition-performance-card is-${member}`}><div className="competition-performance-card-heading"><div><h4>{memberLabel(member)}</h4><p>{values.length ? `آخر ${values.length} جلسات` : "لا توجد جلسات محفوظة"}</p></div><CompetitionTrendBadge values={values} /></div><CompetitionPerformanceSparkline values={values} label={`أداء ${memberLabel(member)}`} color={member === "saif" ? "#559566" : "#b184bf"} /></article>;
}

function CompetitionQuickComparison({ items, member }: { items: CompetitionHistory["sessionItems"]; member: Member }) {
  const compare = (slot: Member) => {
    const sessions = items.filter(item => item.participants.includes(slot));
    const wins = sessions.filter(item => item.winnerKey === slot).length;
    const points = sessions.reduce((sum, item) => sum + (slot === "saif" ? item.saifPoints : item.haneenPoints), 0);
    const timeoutSessions = sessions.filter(item => item.timedOutQuestionCount > 0).length;
    return { sessions: sessions.length, wins, points, timeoutSessions };
  };
  const values = { saif: compare("saif"), haneen: compare("haneen") };
  const pointsFor = (slot: Member) => items.filter(item => item.participants.includes(slot)).sort((a, b) => new Date(a.finishedAt).getTime() - new Date(b.finishedAt).getTime()).map(item => slot === "saif" ? item.saifPoints : item.haneenPoints);
  const performanceSeries = { saif: pointsFor("saif"), haneen: pointsFor("haneen") };
  const maxSessions = Math.max(1, values.saif.sessions, values.haneen.sessions);
  const maxPoints = Math.max(1, values.saif.points, values.haneen.points);
  const metric = (label: string, key: "sessions" | "wins" | "points" | "timeoutSessions", max: number, suffix = "") => <div className="competition-comparison-metric"><div><span>{label}</span><strong>{values.saif[key]}{suffix} · {values.haneen[key]}{suffix}</strong></div><div className="competition-comparison-track"><i className="is-saif" style={{ width: `${(values.saif[key] / max) * 100}%` }} /><i className="is-haneen" style={{ width: `${(values.haneen[key] / max) * 100}%` }} /></div></div>;
  return <section className="competition-quick-comparison" aria-label="مقارنة سريعة بين أداء سيف وحنين"><div className="competition-comparison-heading"><div><p className="card-kicker">مقارنة سريعة</p><h3>أداء {memberLabel(member)} مقابل الطرف الآخر</h3><p>المقارنة مبنية على جلسات السجل المحفوظة فعلياً، وليست ترتيباً مع مستخدمين خارج المنصة.</p></div><div className="competition-comparison-legend"><span><i className="is-saif" />سيف</span><span><i className="is-haneen" />حنين</span></div></div><div className="competition-performance-trends"><CompetitionPerformanceCard member="saif" values={performanceSeries.saif} /><CompetitionPerformanceCard member="haneen" values={performanceSeries.haneen} /></div><div className="competition-comparison-grid">{metric("الجلسات", "sessions", maxSessions)}{metric("الانتصارات", "wins", maxSessions)}{metric("إجمالي النقاط", "points", maxPoints)}{metric("جلسات بها مهلة", "timeoutSessions", maxSessions)}</div></section>;
}

function CompetitionHistoryPanel({ celebrationMatch }: { celebrationMatch?: EvaluatedMatch | null }) {
  const member = useWorkspaceMember();
  const history = trpc.competition.history.useQuery(undefined, { enabled: Boolean(member), refetchInterval: 12_000 });
  const data = history.data as CompetitionHistory | undefined;
  if (history.isLoading) return <CompetitionHistorySkeleton />;
  if (history.isError) return <section className="page-wrap mb-5"><div className="competition-history-state" role="alert"><p className="card-kicker">تعذر تحميل الإنجازات</p><h2>السجل لسه مش جاهز</h2><p>مفيش أي أرقام اتخمنت؛ جرّبوا التحديث عشان نقرأ النتائج المحفوظة فعلاً.</p><button type="button" onClick={() => void history.refetch()}>إعادة المحاولة</button></div></section>;
  if (!data?.sessionCount) return null;
  return <section className="page-wrap mb-5">{celebrationMatch ? <CompetitionAchievementCelebration match={celebrationMatch} compact /> : null}<CompetitionProgressChart items={data.sessionItems} member={member ?? "saif"} />{history.isFetching ? <p className="competition-history-refresh" role="status">جارٍ تحديث الإحصاءات من السجل…</p> : null}<CompetitionQuickComparison items={data.sessionItems} member={member ?? "saif"} /><div className="overflow-hidden rounded-[1.5rem] border border-[#e5ece1] bg-white shadow-[0_14px_35px_rgba(38,61,45,.05)]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#edf0ea] px-5 py-4"><div><p className="card-kicker">سجل المنافسات</p><h2 className="text-lg font-black">جلسات فعلية ونتائج محفوظة</h2><p className="mt-1 text-xs leading-6 text-[#748078]">الدعوات غير المقبولة لا تدخل السجل، بينما الخروج بعد البدء يُحسم ويحفظ بوضوح.</p></div><span className="rounded-full bg-[#eff6ec] px-3 py-1.5 text-xs font-black text-[#416d50]">{data.sessionCount} جلسة</span></div><div className="grid gap-3 border-b border-[#edf0ea] p-5 sm:grid-cols-3"><div className="rounded-2xl bg-[#f5faf3] p-3"><p className="text-xs text-[#718078]">انتصارات سيف الثنائية</p><p className="mt-1 text-2xl font-black text-[#315e40]">{data.wins.saif}</p></div><div className="rounded-2xl bg-[#f5faf3] p-3"><p className="text-xs text-[#718078]">انتصارات حنين الثنائية</p><p className="mt-1 text-2xl font-black text-[#315e40]">{data.wins.haneen}</p></div><div className="rounded-2xl bg-[#fff8ed] p-3"><p className="text-xs text-[#8a6a3d]">جلسات بها مهلة منتهية</p><p className="mt-1 text-2xl font-black text-[#9d7131]">{data.timedOutSessionCount}</p><p className="mt-1 text-[11px] leading-5 text-[#927a58]">جلسة واحدة تُحسب مرة، حتى لو انتهت فيها أكثر من إجابة بالوقت.</p></div></div><div className="space-y-3 p-5">{data.sessionItems.slice(0, 8).map(item => <article key={item.id} className="rounded-2xl border border-[#e5ece1] bg-[#fbfdf9] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-black">{item.engineTitle}</p><p className="mt-1 text-xs text-[#718078]">{item.participants.map(competitorLabel).join(" ضد ")}</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-black ${item.completionReason === "forfeit" ? "bg-[#fff0ed] text-[#9a4d41]" : "bg-[#eff6ec] text-[#416d50]"}`}>{item.completionReason === "forfeit" ? "انتهت بخروج" : "مكتملة"}</span></div><div className="mt-3 grid gap-2 text-xs sm:grid-cols-2"><p className="rounded-xl bg-white px-3 py-2 text-[#53645a]">{item.winnerKey ? `الفائز: ${competitorLabel(item.winnerKey)}` : "النتيجة: تعادل"}</p><p className="rounded-xl bg-white px-3 py-2 text-[#53645a]">{item.loserKey ? `الخاسر: ${competitorLabel(item.loserKey)}` : "لا يوجد خاسر"}{item.forfeitedBy ? ` · خرج ${memberLabel(item.forfeitedBy)}` : ""}</p></div><p className="mt-3 text-xs text-[#748078]">سيف {item.saifPoints} · حنين {item.haneenPoints}{item.mode === "rashed" ? ` · راشد ${item.rashedPoints}` : ""}</p><CompetitionSessionRationalePreview matchId={item.matchId} /></article>)}</div></div></section>;
}

function CompetitionAnnouncementBoard({ celebrationMatch }: { celebrationMatch?: EvaluatedMatch | null }) {
  const member = useWorkspaceMember();
  const history = trpc.competition.history.useQuery(undefined, { enabled: Boolean(member), refetchInterval: 12_000 });
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState<CompetitionHistory["sessionItems"][number] | null>(null);
  const data = history.data as CompetitionHistory | undefined;
  const openDetails = (item: CompetitionHistory["sessionItems"][number]) => { setSelected(item); setOpen(true); };
  if (!data?.sessionCount) return null;
  return <section className="page-wrap mb-5 competition-announcement-entry"><div className="competition-announcement-teaser"><div><p className="card-kicker">لوحة الإعلانات</p><h2>منافساتكم المحفوظة</h2><p>كل منافسة لها بطاقة مختصرة. افتحوا البطاقة لمراجعة تفاصيلها في واجهة مستقلة.</p></div><button type="button" onClick={() => setOpen(true)}><Trophy size={17} />فتح لوحة الإعلانات <span>{data.sessionCount}</span></button></div>{celebrationMatch ? <CompetitionAchievementCelebration match={celebrationMatch} compact /> : null}<Dialog open={open} onOpenChange={value => { setOpen(value); if (!value) setSelected(null); }}><DialogContent className="max-h-[90vh] max-w-4xl overflow-y-auto border-[#e2eadf] bg-[#fffdfa] p-0 text-right" dir="rtl"><DialogHeader className="sticky top-0 z-10 border-b border-[#ecf0e8] bg-[#fffdfa]/95 px-5 py-4 backdrop-blur"><p className="card-kicker">لوحة إعلانات المنافسات</p><DialogTitle>{selected ? "تفاصيل المنافسة" : "اختاروا بطاقة للمراجعة"}</DialogTitle><DialogDescription>{selected ? "التفاصيل أدناه محفوظة من نتيجة المنافسة الفعلية." : "البطاقات لا تعرض الإجابات أثناء المنافسة؛ هي نتائج جلسات مكتملة فقط."}</DialogDescription></DialogHeader>{selected ? <article className="competition-announcement-details"><button type="button" className="competition-announcement-back" onClick={() => setSelected(null)}>← رجوع للبطاقات</button><h3>{`منافسة لؤي · ${selected.engineTitle}`}</h3><p className="competition-announcement-date">{new Date(selected.finishedAt).toLocaleString("ar-EG", { dateStyle: "full", timeStyle: "short" })}</p><div className="competition-announcement-detail-grid"><p><span>المتسابقون</span>{selected.participants.map(competitorLabel).join(" ضد ")}</p><p><span>النمط</span>{selected.mode === "rashed" ? "مواجهة راشد" : "مواجهة بين سيف وحنين"}</p><p><span>النتيجة</span>{selected.winnerKey ? `فاز ${competitorLabel(selected.winnerKey)}` : "تعادل"}</p><p><span>نهاية المنافسة</span>{selected.completionReason === "forfeit" ? `انتهت بخروج ${selected.forfeitedBy ? memberLabel(selected.forfeitedBy) : "أحد المتسابقين"}` : "اكتملت كل الجولات"}</p></div><div className="competition-announcement-scoreline"><span>سيف <b>{selected.saifPoints}</b></span><span>حنين <b>{selected.haneenPoints}</b></span>{selected.mode === "rashed" ? <span>راشد <b>{selected.rashedPoints}</b></span> : null}</div>{selected.timedOutQuestionCount ? <p className="competition-announcement-timeout">سُجلت مهلة في {selected.timedOutQuestionCount} سؤال.</p> : null}<CompetitionSessionRationalePreview matchId={selected.matchId} /></article> : <div className="competition-announcement-cards">{data.sessionItems.map(item => <button key={item.id} type="button" className="competition-announcement-card" onClick={() => openDetails(item)}><div><p className="card-kicker">منافسة لؤي</p><h3>{item.engineTitle}</h3><p>{item.participants.map(competitorLabel).join(" ضد ")}</p></div><div className="competition-announcement-card-meta"><time>{new Date(item.finishedAt).toLocaleDateString("ar-EG", { dateStyle: "medium" })}</time><time>{new Date(item.finishedAt).toLocaleTimeString("ar-EG", { hour: "2-digit", minute: "2-digit" })}</time><span>{item.completionReason === "forfeit" ? "انتهت بخروج" : "مكتملة"}</span></div><strong>عرض التفاصيل ←</strong></button>)}</div>}</DialogContent></Dialog></section>;
}

function CompetitionStatsPanel() {
  const member = useWorkspaceMember();
  const statsQuery = trpc.competition.stats.useQuery(undefined, { enabled: Boolean(member), refetchInterval: 12_000 });
  const stats = statsQuery.data as CompetitionStats | undefined;
  if (!stats?.completedMatches) return null;
  return <section className="page-wrap mb-5"><div className="rounded-[1.5rem] border border-[#e5ece1] bg-[#fbfdf9] p-5 shadow-[0_14px_35px_rgba(38,61,45,.05)]"><p className="card-kicker">إحصاءات من الواقع</p><h2 className="mt-1 text-lg font-black">الدقة وسرعة الإجابة حسب الجولات المكتملة</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-white p-4"><p className="text-sm font-black">سيف</p><p className="mt-2 text-2xl font-black text-[#315e40]">{stats.players.saif.accuracy}%</p><p className="text-xs leading-6 text-[#748078]">دقة من {stats.players.saif.evaluated} إجابات · متوسط {stats.players.saif.averageResponseSeconds === null ? "غير متاح" : `${stats.players.saif.averageResponseSeconds} ث`} </p></div><div className="rounded-2xl bg-white p-4"><p className="text-sm font-black">حنين</p><p className="mt-2 text-2xl font-black text-[#315e40]">{stats.players.haneen.accuracy}%</p><p className="text-xs leading-6 text-[#748078]">دقة من {stats.players.haneen.evaluated} إجابات · متوسط {stats.players.haneen.averageResponseSeconds === null ? "غير متاح" : `${stats.players.haneen.averageResponseSeconds} ث`}</p></div></div>{stats.subjects.length ? <div className="mt-4 space-y-2">{stats.subjects.slice(0, 4).map(subject => <div key={subject.subjectName} className="flex items-center justify-between rounded-xl bg-white px-3 py-2.5 text-xs"><span className="font-black">{subject.subjectName}</span><span className="font-bold text-[#55725c]">{subject.accuracy}% دقة · {subject.evaluated} إجابات</span></div>)}</div> : null}</div></section>;
}

export default function CompetitionPage() {
  const member = useWorkspaceMember();
  const active = trpc.competition.currentMatch.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 4_000 });
  const latest = trpc.competition.latestMatch.useQuery({ memberSlot: member ?? "saif" }, { enabled: Boolean(member), refetchInterval: 12_000 });
  const [dismissedFinishedMatchId, setDismissedFinishedMatchId] = useState<number | null>(null);
  const [celebrationMatchId, setCelebrationMatchId] = useState<number | null>(null);
  const lastActiveMatchIdRef = useRef<number | null>(null);
  const activeMatch = active.data as EvaluatedMatch | null | undefined;
  const latestMatch = latest.data as EvaluatedMatch | null | undefined;
  useEffect(() => {
    if (activeMatch && activeMatch.match.status !== "finished") lastActiveMatchIdRef.current = activeMatch.match.id;
    const finishedId = latestMatch?.match.status === "finished" ? latestMatch.match.id : null;
    if (finishedId && finishedId === lastActiveMatchIdRef.current) setCelebrationMatchId(current => current === finishedId ? current : finishedId);
  }, [activeMatch?.match.id, activeMatch?.match.status, latestMatch?.match.id, latestMatch?.match.status]);
  const celebrationMatch = celebrationMatchId && latestMatch?.match.id === celebrationMatchId && latestMatch.match.status === "finished" ? latestMatch : null;
  const match = activeMatch ?? (latestMatch?.match.status === "finished" && latestMatch.match.id !== dismissedFinishedMatchId ? latestMatch : null);
  if (match?.match.mode === "rashed" && match.match.status === "finished") return <><CompetitionSoundPreferenceBar />{celebrationMatch ? <CompetitionAchievementCelebration match={celebrationMatch} /> : null}<CompetitionForfeitNotice match={match} /><CompetitionRationaleArchivePanel /><CompetitionRashedFinalResult match={match} onDismiss={() => setDismissedFinishedMatchId(match.match.id)} /></>;
  if (activeMatch && ["question_active", "evaluating"].includes(activeMatch.match.status)) return <><CompetitionSoundPreferenceBar /><CompetitionQuestionTimer match={activeMatch} /><CompetitionLeaveControl match={activeMatch} /><CompetitionOpponentBanner match={activeMatch} /><CompetitionRationaleArchivePanel /><CompetitionExamRoom match={activeMatch} /></>;
  if (match && ["showing_result", "finished"].includes(match.match.status)) return <><CompetitionSoundPreferenceBar />{match.match.status === "finished" && celebrationMatch ? <CompetitionAchievementCelebration match={celebrationMatch} /> : null}<CompetitionForfeitNotice match={match} />{match.match.status === "showing_result" ? <CompetitionLeaveControl match={match} /> : null}<CompetitionOpponentBanner match={match} /><CompetitionRationaleArchivePanel /><CompetitionManualReviewPanel match={match} />{match.match.mode === "duel" ? <CompetitionLoayReviewPanel match={match} /> : null}<CompetitionRashedRoundResult match={match} /><CompetitionEvaluationStage match={match} onDismiss={match.match.status === "finished" ? () => setDismissedFinishedMatchId(match.match.id) : undefined} /></>;
  return <>{activeMatch ? <><CompetitionQuestionTimer match={activeMatch} /><CompetitionLeaveControl match={activeMatch} /></> : null}<CompetitionRationaleArchivePanel /><CompetitionStatsPanel /><CompetitionPageLegacy /><CompetitionAnnouncementBoard celebrationMatch={celebrationMatch} /></>;
}
